function compactUsd(value){const n=Number(value);if(!Number.isFinite(n))return '—';if(Math.abs(n)>=1e9)return `$${(n/1e9).toFixed(2)}B`;if(Math.abs(n)>=1e6)return `$${(n/1e6).toFixed(2)}M`;return `$${n.toFixed(2)}`}
function majorPercent(value){return value===null||value===undefined?'—':`${Number(value)>=0?'+':''}${Number(value).toFixed(2)}%`}
function majorMarketCard(item){const f=item.forecast||{},w=item.windows||{},w30=w['30m']||{},w4h=w['4h']||{};return `<article class="major-market-card ${f.stance==='偏强'?'strong':f.stance==='偏弱'?'weak':'flat'}"><div class="major-head"><div><p>${item.market_note||'大盘观察'}</p><h3>${item.symbol}</h3></div><b>${f.stance||'观察'}</b></div><div class="major-price"><strong>${money(item.price)}</strong><span class="${changeClass(item.change_24h)}">24H ${majorPercent(item.change_24h)}</span></div><div class="major-grid"><span>30M <em class="${changeClass(w30.price_change)}">${majorPercent(w30.price_change)}</em></span><span>4H <em class="${changeClass(w4h.price_change)}">${majorPercent(w4h.price_change)}</em></span><span>资费 <em class="${changeClass(item.funding_rate)}">${majorPercent(item.funding_rate)}</em></span><span>基差 <em class="${changeClass(item.basis)}">${majorPercent(item.basis)}</em></span><span>持仓 <em>${compactUsd(item.open_interest)}</em></span><span>人数比 <em>${item.long_short_ratio?Number(item.long_short_ratio).toFixed(3):'—'}</em></span></div><p class="major-forecast">${f.forecast||'等待数据共振。'}</p><small>${f.reason||''} · ${item.updated_at||''}</small></article>`}
function renderMajorMarkets(items){const target=byId('majorMarketOverview');if(!target)return;if(!items?.length){target.innerHTML='<p class="empty-alert">BTC / ETH / SOL 大盘风向暂时无法读取。</p>';return}target.innerHTML=`<div class="major-market-title"><div><p class="eyebrow">MARKET CONTEXT</p><h3>大盘风向：BTC · ETH · SOL</h3></div><small>BTC 用来衡量大盘，ETH/SOL 看风险偏好联动</small></div><div class="major-market-grid">${items.map(majorMarketCard).join('')}</div>`}
function dashboardExchangePrices(row){const prices=row.exchange_prices||{},order=[['Binance','BN'],['OKX','OK'],['Bybit','BY']];return `<div class="dashboard-price-stack">${order.map(([key,label])=>{const value=prices[key],role=key===row.buy_exchange?'low':key===row.sell_exchange?'high':'';return `<span class="${role}"><b>${label}</b><em>${value?money(value):'—'}</em>${role?`<i>${role==='low'?'低':'高'}</i>`:''}</span>`}).join('')}</div>`}
async function loadDashboard(){const data=await (await fetch('/api/dashboard')).json();renderMajorMarkets(data.majors||[]);byId('bestSpread').textContent=data.summary.best_spread.toFixed(3)+'%';byId('markets').textContent=data.summary.markets_scanned;byId('activeStrategies').textContent=data.summary.active_strategies;byId('mode').textContent=data.summary.mode;byId('updated').textContent='最近更新 '+new Date().toLocaleTimeString('zh-CN');byId('opportunities').innerHTML=data.opportunities.map(x=>`<tr><td class="symbol">${x.symbol}</td><td>${dashboardExchangePrices(x)}</td><td>${money(x.buy_price)}<span class="exchange">${x.buy_exchange}</span></td><td>${money(x.sell_price)}<span class="exchange">${x.sell_exchange}</span></td><td class="profit">${x.spread.toFixed(3)}%</td><td class="profit">+${x.estimated_profit.toFixed(3)}%</td><td class="funding ${x.funding>=0?'profit':''}">${x.funding>=0?'+':''}${x.funding.toFixed(4)}%</td><td>${x.updated_at}</td></tr>`).join('')}
function dailyTrendItem(item){return `<article><b>${item.symbol}</b><span class="${changeClass(item.change_24h)}">24H ${displayChange(item.change_24h)}</span><small>7D ${displayChange(item.change_7d)}</small></article>`}
function hornTimeframeLabel(item){return item.timeframe==='continue'?'延续':item.timeframe.toUpperCase()}
function hornSignalItem(item,index){return `<article><b>${index+1}</b><div class="horn-symbol-cell"><button class="symbol-detail-trigger" onclick="openSymbolDetail('${item.symbol}')">${item.symbol}</button><a class="kline-link horn-kline-link" href="${coinglassKlineUrl(item.symbol)}" target="_blank" rel="noopener noreferrer" title="在 CoinGlass 查看 ${item.symbol} K线">K线</a></div><span class="horn-timeframe">${hornTimeframeLabel(item)}</span><span>结构分 <em class="horn-score">${Number(item.score).toFixed(1)}</em></span><span>价格 <em class="${changeClass(item.price_change)}">${percent(item.price_change)}</em></span><span>OI <em class="${changeClass(item.oi_change)}">${percent(item.oi_change)}</em></span><span>人数比 <em class="${changeClass(item.ratio_change)}">${percent(item.ratio_change)}</em></span><span class="${item.cvd_confirmed?'horn-cvd-confirmed':'horn-cvd-divergent'}">CVD ${item.cvd_confirmed?'确认上涨':'背离/未确认'}</span></article>`}
function earlyFocusItem(item,index){const strong=item.signal_type==='strong_focus',cvdUp=Number(item.cvd_change_5)>0;return `<article class="early-focus-item ${strong?'strong':'prelaunch'}"><b>${index+1}</b><div class="horn-symbol-cell"><button class="symbol-detail-trigger" onclick="openSymbolDetail('${item.symbol}')">${item.symbol}</button><a class="kline-link horn-kline-link" href="${coinglassKlineUrl(item.symbol)}" target="_blank" rel="noopener noreferrer">K线</a></div><strong class="trend-stage stage-${item.stage_number}">${item.stage_label}</strong><span>5根价格 <em class="${changeClass(item.price_change_5)}">${percent(item.price_change_5)}</em></span><span>持仓 <em class="${changeClass(item.oi_change_5)}">${percent(item.oi_change_5)}</em></span><span>人数比 <em class="${changeClass(item.ratio_change_5)}">${percent(item.ratio_change_5)}</em></span><span>CVD <em class="${cvdUp?'positive':'negative'}">${cvdUp?'上涨确认':'尚未确认'}</em></span><span>量能 <em>${Number(item.volume_ratio||0).toFixed(2)}倍</em></span><p>${item.stage_reason}</p></article>`}
function automationStatusMarkup(statuses){const values=Object.values(statuses||{});return values.length?`<div class="automation-status-row">${values.map(item=>`<span class="${item.ran_today?'ok':'warn'}"><b>${item.label}</b><em>${item.ran_today?'今日已执行':'今日未成功'}</em><small>最近成功：${item.last_success_at||'暂无'}${item.last_error?` · 错误：${item.last_error}`:''}</small></span>`).join('')}</div>`:''}
function renderAutomationStatus(anchorId,statuses){const anchor=byId(anchorId);if(!anchor?.parentElement)return;anchor.parentElement.querySelector('.automation-status-row')?.remove();anchor.insertAdjacentHTML('beforebegin',automationStatusMarkup(statuses))}
async function loadDailyTrends(){const data=await (await fetch('/api/daily-report/trends')).json();renderAutomationStatus('dailyHorn30m',data.automation_status);byId('dailyEarlyFocus').innerHTML=data.early_focus?.length?data.early_focus.map(earlyFocusItem).join(''):'<p class="empty-alert">今日暂未出现启动前蓄势或5根强启动重点信号。</p>';byId('dailyHorn30m').innerHTML=data.horn_30m?.length?data.horn_30m.map(hornSignalItem).join(''):'<p class="empty-alert">今日暂无 30 分钟犄型候选。</p>';byId('dailyHorn4h').innerHTML=data.horn_4h?.length?data.horn_4h.map(hornSignalItem).join(''):'<p class="empty-alert">今日暂无 4H 犄型候选。</p>';byId('dailyHornContinue').innerHTML=data.horn_continue?.length?data.horn_continue.map(hornSignalItem).join(''):'<p class="empty-alert">今日暂无犄角延续候选。</p>'}
async function loadDailyListings(){const data=await (await fetch('/api/daily-report/listings')).json();byId('dailyListings').innerHTML=data.events.length?data.events.map(item=>`<article><b>${item.symbol}</b><span class="listing-${item.type==='上架'?'up':'down'}">${item.type}</span><small>${item.exchange} · ${item.occurred_at}</small></article>`).join(''):'<p class="empty-alert">已建立当前 Binance 永续合约基线；最近 30 天暂无上下架变化。</p>'}
async function loadStrategies(){const data=await (await fetch('/api/strategies')).json();byId('strategyList').innerHTML=data.map(x=>`<article class="strategy"><div><h3>${x.name}<span class="tag ${x.enabled?'':'off'}">${x.enabled?'运行中':'已暂停'}</span></h3><p>${x.mode} · ${x.symbol}</p></div>${authState.is_admin?`<button onclick="toggleStrategy(${x.id})">${x.enabled?'暂停':'启用'}</button>`:''}</article>`).join('')}
async function toggleStrategy(id){await fetch('/api/strategies/'+id,{method:'PATCH',headers:{'X-CSRF-Token':authState.csrf_token}});loadStrategies();loadDashboard()}
function openModal(){byId('modal').classList.remove('hidden')}function closeModal(){byId('modal').classList.add('hidden')}
async function saveStrategy(e){e.preventDefault();const res=await fetch('/api/strategies',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({name:byId('name').value,mode:byId('strategyMode').value,symbol:byId('symbol').value})});if(!res.ok){alert((await res.json()).error);return}e.target.reset();closeModal();loadStrategies();loadDashboard()}
function percent(value){return `${value>=0?'+':''}${Number(value).toFixed(4)}%`}
function signClass(value){return Number(value)>=0?'positive':'negative'}
function intervalClass(hours){return [1,2,4,8].includes(Number(hours))?`interval-${hours}`:'interval-other'}
function displayFunding(value){return value===null||value===undefined?'—':percent(value)}
function fundingStack(row){return `<div class="funding-stack"><span class="funding-item"><b>当前</b><span class="${signClass(row.funding_rate)}">${displayFunding(row.funding_rate)}</span></span><span class="funding-item"><b>上期</b><span class="${signClass(row.funding_previous)}">${displayFunding(row.funding_previous)}</span></span><span class="funding-item"><b>24H</b><span class="${signClass(row.funding_24h)}">${displayFunding(row.funding_24h)}</span></span><span class="funding-item"><b>3D</b><span class="${signClass(row.funding_3d)}">${displayFunding(row.funding_3d)}</span></span><span class="funding-item"><b>7D</b><span class="${signClass(row.funding_7d)}">${displayFunding(row.funding_7d)}</span></span><span class="funding-item"><b>30D</b><span class="${signClass(row.funding_30d)}">${displayFunding(row.funding_30d)}</span></span></div>`}
const trendPeriods=[['change_5m','5MIN'],['change_15m','15MIN'],['change_30m','30MIN'],['change_1h','1H'],['change_12h','12H'],['change_24h','24H'],['change_3d','3D'],['change_7d','7D']];
const spotSortLabels={basis:'基差',funding_rate:'当前资费',funding_previous:'上期资费',funding_24h:'24H 资费',funding_3d:'3D 资费',funding_7d:'7D 资费',funding_30d:'30D 资费',change_5m:'5MIN 涨跌幅',change_15m:'15MIN 涨跌幅',change_30m:'30MIN 涨跌幅',change_1h:'1H 涨跌幅',change_12h:'12H 涨跌幅',change_24h:'24H 涨跌幅',change_3d:'3D 涨跌幅',change_7d:'7D 涨跌幅',open_spread:'开差',close_spread:'平差'};
function changeClass(value){return value===null||value===undefined?'neutral':Number(value)>0?'positive':Number(value)<0?'negative':'neutral'}
function displayChange(value){return value===null||value===undefined?'—':percent(value)}
function trendLights(row){return `<div class="trend-lights">${trendPeriods.map(([key,label])=>`<span class="trend-light ${changeClass(row[key])}" title="${label} ${displayChange(row[key])}"><i></i><em>${label}</em></span>`).join('')}</div>`}
function priceChangeStack(row){return `<div class="change-stack">${trendPeriods.map(([key,label])=>`<span class="change-item"><b>${label}</b><span class="${changeClass(row[key])}">${displayChange(row[key])}</span></span>`).join('')}</div>`}
const exchangeIcon={Binance:'/static/exchanges/binance.png',Gate:'/static/exchanges/gate.png',Bitget:'/static/exchanges/bitget.png',Bybit:'/static/exchanges/bybit.png',OKX:'/static/exchanges/okx.png'};
function exchangeName(exchange){const icon=exchangeIcon[exchange];return `${icon?`<img class="exchange-logo" src="${icon}" alt="${exchange}">`:''}${exchange}`}
function coinglassKlineUrl(symbol){return `https://www.coinglass.com/tv/zh/Binance_${encodeURIComponent(symbol.replace('/',''))}`}
function liquidityLevel(value){const amount=Number(value||0);return amount>=10000000?'safe':amount>=5000000?'warn-light':amount>=1000000?'warn-medium':'warn-deep'}
function liquidityAmount(value){const amount=Number(value);if(!Number.isFinite(amount)||amount<=0)return '—';return amount>=1e9?`$${(amount/1e9).toFixed(2)}B`:`$${(amount/1e6).toFixed(2)}M`}
function liquidityMetric(label,value){return `<span class="liquidity-metric ${liquidityLevel(value)}"><b>${label}</b><i>${liquidityAmount(value)}</i></span>`}
function spotLiquidity(row){return `<div class="liquidity-stack">${liquidityMetric('交易量',row.spot_volume)}</div>`}
function futuresLiquidity(row){return `<div class="liquidity-stack">${liquidityMetric('持仓量',row.futures_open_interest)}${liquidityMetric('交易量',row.futures_volume)}</div>`}
function spotTransferStatus(row){const chains=Array.isArray(row.transfer_networks)?row.transfer_networks:[];if(!chains.length)return `<span class="transfer-status pending">充提待确认</span>`;const deposits=chains.filter(chain=>chain.deposit_open).length,withdrawals=chains.filter(chain=>chain.withdraw_open).length,closed=chains.filter(chain=>!chain.deposit_open||!chain.withdraw_open),payload=encodeURIComponent(JSON.stringify(chains));return `<span class="transfer-status ${closed.length?'transfer-alert':''}" data-transfer-chains="${payload}" onmouseenter="showTransferTip(this)" onmouseleave="destroyFloatingPopup()">充${deposits}/${chains.length} · 提${withdrawals}/${chains.length}${closed.length?` · ${closed.length}链关闭`:''}</span>`}
function showTransferTip(trigger){destroyFloatingPopup();let chains=[];try{chains=JSON.parse(decodeURIComponent(trigger.dataset.transferChains||''))}catch(error){return}const open=(key)=>chains.filter(chain=>chain[key]).map(chain=>chain.name).join('/')||'关闭',closed=chains.filter(chain=>!chain.deposit_open||!chain.withdraw_open).map(chain=>chain.name).join('/');const popup=document.createElement('div');popup.dataset.floatingDetail='transfer';popup.className='floating-detail-popup transfer-popup';popup.innerHTML=`<div>充值：<b>${open('deposit_open')}</b></div><div>提现：<b>${open('withdraw_open')}</b>${closed?` <em>${closed}（关闭）</em>`:''}</div>`;document.body.appendChild(popup);positionFloatingPopup(popup,trigger)}
function spotRows(symbols){
  return symbols.map(group=>{
    const contract=group.rows[0],span=group.rows.length;
    const shared=`<td class="contract-cell" rowspan="${span}">${exchangeName('Binance')} 合约</td><td rowspan="${span}">${futuresLiquidity(contract)}</td><td class="${signClass(contract.basis)} numeric" rowspan="${span}">${percent(contract.basis)}</td><td rowspan="${span}">${fundingStack(contract)}</td><td rowspan="${span}"><span class="interval-badge ${intervalClass(contract.funding_interval_hours)}">${contract.funding_interval_hours}H</span><span class="exchange">下次 ${fundingClock(contract.next_funding_time)}</span></td>`;
    return group.rows.map((row,index)=>{
      return `<tr>${index===0?`<td class="symbol" rowspan="${span}">${trendLights(contract)}<div><button class="symbol-detail-trigger ${group.delisting_announced?'delisting-symbol':''}" onclick="openSymbolDetail('${group.symbol}')">${group.symbol}</button><a class="kline-link" href="${coinglassKlineUrl(group.symbol)}" target="_blank" rel="noopener noreferrer">K线</a></div><div class="symbol-basis-opening">${basisOpeningMarkup(group.basis_opening,`spot:${group.symbol}`)}</div></td><td class="price-change-cell" rowspan="${span}">${priceChangeStack(contract)}</td>`:''}<td>${spotLiquidity(row)}</td><td class="spot-cell">${exchangeName(row.long_exchange)}${spotTransferStatus(row)}</td>${index===0?shared:''}<td class="${signClass(row.open_spread)} numeric">${percent(row.open_spread)}</td><td class="${signClass(row.close_spread)} numeric">${percent(row.close_spread)}</td></tr>`;
    }).join('');
  }).join('');
}
function showMarketRefreshCountdown(seconds){clearInterval(marketRefreshCountdownTimer);let remaining=Math.max(0,Number(seconds)||0);const target=byId('spotFuturesCountdown');const render=()=>{target.textContent=remaining>0?` · 下次行情同步约 ${remaining} 秒`:' · 正在等待下一轮行情同步…'};render();marketRefreshCountdownTimer=setInterval(()=>{remaining=Math.max(0,remaining-1);render();if(remaining===0)clearInterval(marketRefreshCountdownTimer)},1000)}
async function loadSpotFutures(manual=false){
  if(spotFuturesLoading)return;
  spotFuturesLoading=true;
  const status=byId('spotFuturesUpdated'),bnOnly=byId('binanceSpotOnly').checked;
  if(manual)status.textContent='正在读取已缓存的行情数据…';
  try{
    const response=await fetch('/api/spot-futures?page='+spotFuturesPage+'&binance_spot_only='+(bnOnly?'1':'0')+'&funding_interval='+encodeURIComponent(spotFundingInterval)+'&symbol='+encodeURIComponent(spotFuturesSearch)+'&sort_by='+spotSort.key+'&sort_direction='+spotSort.direction);
    const data=await response.json();
    if(!response.ok)throw new Error(data.error||'行情服务暂不可用');
    destroyFloatingPopup();spotBasisOpenings=Object.fromEntries(data.symbols.map(group=>[group.symbol,group.basis_opening]));byId('spotFuturesRows').innerHTML=data.symbols.length?spotRows(data.symbols):'<tr><td colspan="11" class="loading">没有符合条件的交易对。</td></tr>';
    spotFuturesHasData=true;
    updateSortHeaders();
    byId('pageInfo').textContent=`第 ${data.page} / ${data.pages} 页 · 共 ${data.total_symbols} 个币种`;
    const pageSelect=byId('spotFuturesPageSelect');
    pageSelect.innerHTML=Array.from({length:data.pages},(_,index)=>`<option value="${index+1}" ${index+1===data.page?'selected':''}>${index+1}</option>`).join('');
    byId('previousPage').disabled=data.page<=1;
    byId('nextPage').disabled=data.page>=data.pages;
    const failed=Object.keys(data.errors||{});
    const detail=failed.length?failed.join('、')+' 行情暂不可用':`已对全部 ${data.total_symbols} 个币种排序后分页 · 当前按${spotSortLabels[spotSort.key]}排序`;
    status.textContent=`最近更新 ${data.updated_at} · ${detail}`;
    showMarketRefreshCountdown(data.next_refresh_in_seconds);
  }catch(error){
    if(!spotFuturesHasData)byId('spotFuturesRows').innerHTML=`<tr><td colspan="11" class="loading">${error.message}</td></tr>`;
    status.textContent=spotFuturesHasData?'本次更新失败，已保留上一组有效数据。':error.message;
  }finally{spotFuturesLoading=false}
}
function groupSortValue(group){const rows=group.rows;if(spotSort.key==='open_spread'||spotSort.key==='close_spread')return Math.max(...rows.map(row=>Number(row[spotSort.key])));return Number(rows[0][spotSort.key])}
function sortGroups(groups){return [...groups].sort((a,b)=>{const delta=groupSortValue(a)-groupSortValue(b);return spotSort.direction==='desc'?-delta:delta})}
function updateSortHeaders(){document.querySelectorAll('.sort-header').forEach(button=>{const active=button.dataset.sort===spotSort.key;button.classList.toggle('active',active);button.textContent=button.textContent.replace(/ [↑↓]$/,'')+(active?(spotSort.direction==='desc'?' ↓':' ↑'):'')})}
function setSpotSort(key){spotSort=spotSort.key===key?{key,direction:spotSort.direction==='desc'?'asc':'desc'}:{key,direction:'desc'};spotFuturesPage=1;updateSortHeaders();loadSpotFutures(true)}
function changeSpotFuturesPage(change){spotFuturesPage=Math.max(1,spotFuturesPage+change);loadSpotFutures(true)}
function selectSpotFuturesPage(page){spotFuturesPage=Math.max(1,Number(page)||1);loadSpotFutures(true)}
function setBinanceSpotFilter(){spotFuturesPage=1;loadSpotFutures(true)}
function setSpotFundingInterval(interval){spotFundingInterval=interval;spotFuturesPage=1;document.querySelectorAll('.spot-period-filter').forEach(button=>button.classList.toggle('active',button.dataset.spotPeriod===interval));loadSpotFutures(true)}
async function loadSymbolSuggestions(scope,query){const panel=byId(scope+'Suggestions');const normalized=query.trim();if(!normalized){panel.innerHTML='';panel.classList.add('hidden');return}const requestId=++suggestionRequest;try{const response=await fetch('/api/symbol-suggestions?q='+encodeURIComponent(normalized));const data=await response.json();if(requestId!==suggestionRequest)return;panel.innerHTML=data.items.length?data.items.map(item=>`<button type="button" class="symbol-suggestion" onclick="selectSymbolSuggestion('${scope}','${item.symbol}','${item.label}')"><span>${item.name||item.symbol.split('/')[0]}</span><small>${item.symbol}${item.live?'':' · 暂无当前行情'}</small></button>`).join(''):'<p class="no-suggestion">没有匹配的币种</p>';panel.classList.remove('hidden')}catch(error){panel.innerHTML='';panel.classList.add('hidden')}}
function selectSymbolSuggestion(scope,symbol,label){const input=byId(scope+'Search');input.value=label;byId(scope+'Suggestions').classList.add('hidden');if(scope==='spotFutures'){spotFuturesSearch=symbol;spotFuturesPage=1;loadSpotFutures(true);return}dualFuturesSearch=symbol;dualFuturesPage=1;loadDualFutures(true)}
function setSpotFuturesSearch(value){spotFuturesSearch=value.trim();spotFuturesPage=1;loadSymbolSuggestions('spotFutures',value);clearTimeout(spotFuturesSearchTimer);spotFuturesSearchTimer=setTimeout(()=>loadSpotFutures(true),180)}
function setDualFuturesSearch(value){const query=value.trim();dualFuturesSearch=query;dualFuturesPage=1;loadSymbolSuggestions('dualFutures',query);clearTimeout(dualFuturesSearchTimer);dualFuturesSearchTimer=setTimeout(()=>loadDualFutures(true),180)}
function dualDisplayPercent(value){return value===null||value===undefined?'—':percent(value)}
function dualTrendLights(group){return `<div class="trend-lights">${trendPeriods.map(([key,label])=>`<span class="trend-light ${changeClass(group['binance_'+key])}" title="${label} ${displayChange(group['binance_'+key])}"><i></i><em>${label}</em></span>`).join('')}</div>`}
function dualPriceChanges(group){return `<div class="change-stack">${trendPeriods.map(([key,label])=>`<span class="change-item"><b>${label}</b><span class="${changeClass(group['binance_'+key])}">${displayChange(group['binance_'+key])}</span></span>`).join('')}</div>`}
function dualInterval(value){return value===null||value===undefined?'—':`${value}H`}
function dualMid(row,side){const bid=Number(row[`${side}_bid`]),ask=Number(row[`${side}_ask`]);return Number.isFinite(bid)&&Number.isFinite(ask)?(bid+ask)/2:null}
function marketPrice(value){const n=Number(value);if(!Number.isFinite(n))return '—';if(Math.abs(n)>=100)return n.toFixed(2);if(Math.abs(n)>=1)return n.toFixed(4);return n.toFixed(6)}
function fundingClock(value){const text=String(value||'--').trim();return text.includes(' ')?text.split(' ').pop():text}
function dualFundingCap(row,side){const cap=row[`${side}_funding_cap`]??row[`${side}_funding_upper`]??row[`${side}_funding_limit`];return cap===null||cap===undefined?'2%':dualDisplayPercent(cap)}
function dualFundingLine(row,side){const rate=row[`${side}_funding_rate`],next=fundingClock(row[`${side}_next_funding_time`]);return `<span class="dual-card-funding"><b>资费 / 上限 / 倒计时</b><em class="${changeClass(rate)}">${dualDisplayPercent(rate)}</em><i class="dual-sep">/</i><i class="dual-cap">${dualFundingCap(row,side)}</i><i class="dual-sep">/</i><small>${next}</small></span>`}
function dualCardLiquidity(oi,volume){return `<span class="dual-card-liquidity">${liquidityMetric('持仓量',oi)}<i>/</i>${liquidityMetric('24H量',volume)}</span>`}
function dualExchangeCard(row,side){const exchange=row[`${side}_exchange`],basis=row[`${side}_basis`],price=dualMid(row,side),oi=row[`${side}_open_interest`],volume=row[`${side}_volume`],label=side==='long'?'多':'空';return `<div class="dual-exchange-card ${side}"><header><span>${exchangeName(exchange)} <em>合约</em></span><div><i class="interval-badge ${intervalClass(row[`${side}_funding_interval_hours`])}">${dualInterval(row[`${side}_funding_interval_hours`])}</i><i class="dual-side ${side}">${label}</i></div></header><dl><div><dt>基差</dt><dd class="${changeClass(basis)}">${dualDisplayPercent(basis)}</dd></div>${dualFundingLine(row,side)}<div><dt>现价</dt><dd>${marketPrice(price)}</dd></div><div><dt>持仓量 / 24H交易量</dt><dd>${dualCardLiquidity(oi,volume)}</dd></div></dl></div>`}
function dualFundingDifference(row){return `<div class="${changeClass(row.funding_difference)} dual-funding-diff"><b>${dualDisplayPercent(row.funding_difference)}</b><small>${row.funding_settlement_label||'结算时间待同步'}</small></div>`}
function dualLiquidity(row){return `<div class="liquidity-stack dual-liquidity"><span><b>多</b>${liquidityMetric('持仓量',row.long_open_interest)}${liquidityMetric('交易量',row.long_volume)}</span><span><b>空</b>${liquidityMetric('持仓量',row.short_open_interest)}${liquidityMetric('交易量',row.short_volume)}</span></div>`}
function componentMaps(row){return {long:Object.fromEntries((row.long_index_components||[]).map(item=>[item.source,item])),short:Object.fromEntries((row.short_index_components||[]).map(item=>[item.source,item]))}}
function localIndexOverlap(row){const {long,short}=componentMaps(row);return Object.keys(long).reduce((total,source)=>total+(short[source]?Math.min(Number(long[source].weight)||0,Number(short[source].weight)||0):0),0)*100}
function componentCompareRows(row){const {long,short}=componentMaps(row);return [...new Set([...Object.keys(long),...Object.keys(short)])].sort().map(source=>{const left=long[source],right=short[source],name=left?.name||right?.name,first=Number(left?.weight||0)*100,second=Number(right?.weight||0)*100;return `<article class="component-compare"><div><b>${name}</b><span>${row.long_exchange} ${first.toFixed(2)}% · ${row.short_exchange} ${second.toFixed(2)}%</span></div><div class="component-compare-bar"><i class="long" style="width:${first.toFixed(2)}%"></i><i class="short" style="width:${second.toFixed(2)}%"></i></div></article>`}).join('')}
function dualIndexOverlap(row){const longComponents=row.long_index_components||[],shortComponents=row.short_index_components||[];if(row.index_overlap===null||row.index_overlap===undefined)return `<span class="common-index-empty">${row.index_status||'成分待同步'}</span>`;if(!longComponents.length||!shortComponents.length)return '<span class="common-index-empty">指数成分不可用</span>';const overlap=Math.max(0,Math.min(100,localIndexOverlap(row)));return `<div class="common-index" data-common-index-id="${row._commonIndexId}"><b class="common-index-trigger" onmouseenter="showCommonIndexTip(this)" onmouseleave="destroyFloatingPopup()">${overlap.toFixed(2)}%</b></div>`}
function dualResultPanel(row){return `<div class="dual-result-panel"><div><span>开差</span><b class="${signClass(row.open_spread)}">${percent(row.open_spread)}</b></div><div><span>平差</span><b class="${signClass(row.close_spread)}">${percent(row.close_spread)}</b></div><div><span>资费差</span>${dualFundingDifference(row)}</div><div><span>共指</span>${dualIndexOverlap(row)}</div></div>`}
function dualRows(symbols){return symbols.map(group=>{const span=group.rows.length;return group.rows.map((row,index)=>`<tr class="${index===0?'dual-group-start ':index===span-1?'dual-group-end':'dual-group-body'}">${index===0?`<td class="symbol" rowspan="${span}">${dualTrendLights(group)}<div><button class="symbol-detail-trigger ${group.delisting_announced?'delisting-symbol':''}" onclick="openSymbolDetail('${group.symbol}')">${group.symbol}</button><a class="kline-link" href="${coinglassKlineUrl(group.symbol)}" target="_blank" rel="noopener noreferrer">K线</a></div><div class="symbol-basis-opening">${basisOpeningMarkup(group.basis_opening,`dual:${group.symbol}`)}</div></td><td class="price-change-cell" rowspan="${span}">${dualPriceChanges(group)}</td>`:''}<td class="dual-leg-cell">${dualExchangeCard(row,'long')}</td><td class="dual-leg-cell">${dualExchangeCard(row,'short')}</td><td class="dual-result-cell">${dualResultPanel(row)}</td></tr>`).join('')}).join('')}
function positionFloatingPopup(popup,trigger){const rect=trigger.getBoundingClientRect(),width=Math.min(540,window.innerWidth-32),left=Math.max(16,Math.min(window.innerWidth-width-16,rect.right-width));popup.style.width=`${width}px`;popup.style.left=`${left}px`;if(rect.top<360){popup.style.top=`${rect.bottom+9}px`}else{popup.style.top=`${rect.top-9}px`;popup.style.transform='translateY(-100%)'}}
function destroyFloatingPopup(){document.querySelector('[data-floating-detail]')?.remove()}
function showCommonIndexTip(trigger){destroyFloatingPopup();const row=dualIndexRows.get(trigger.closest('.common-index')?.dataset.commonIndexId);if(!row)return;const overlap=Math.max(0,Math.min(100,localIndexOverlap(row))),popup=document.createElement('div'),path=`${row.long_exchange} → ${row.short_exchange}`;popup.dataset.floatingDetail='common-index';popup.className='floating-detail-popup common-index-popup';popup.innerHTML=`<header><span><i class="index-key long"></i>${exchangeName(row.long_exchange)}</span><b class="index-path">${path}</b><span><i class="index-key short"></i>${exchangeName(row.short_exchange)}</span></header><div class="component-compare-list">${componentCompareRows(row)}</div><div class="common-index-bar"><i style="width:${overlap.toFixed(2)}%"></i></div><small>共同成分权重 ${overlap.toFixed(2)}%</small>`;document.body.appendChild(popup);positionFloatingPopup(popup,trigger)}
function showDualRefreshCountdown(seconds){clearInterval(dualMarketRefreshCountdownTimer);let remaining=Math.max(0,Number(seconds)||0),target=byId('dualFuturesCountdown');const render=()=>{target.textContent=remaining>0?` · 下次行情同步约 ${remaining} 秒`:' · 正在等待下一轮行情同步…'};render();dualMarketRefreshCountdownTimer=setInterval(()=>{remaining=Math.max(0,remaining-1);render();if(remaining===0)clearInterval(dualMarketRefreshCountdownTimer)},1000)}
function updateDualSortHeaders(){document.querySelectorAll('.dual-sort-header').forEach(button=>{const active=button.dataset.dualSort===dualSort.key;button.classList.toggle('active',active);button.textContent=button.textContent.replace(/ [↕↓↑]$/,'')+(active?(dualSort.direction==='desc'?' ↓':' ↑'):'')})}
function setDualSort(key){dualSort=dualSort.key===key?{key,direction:dualSort.direction==='desc'?'asc':'desc'}:{key,direction:'desc'};dualFuturesPage=1;updateDualSortHeaders();loadDualFutures(true)}
function setDualIncludeBybitOkx(checked){dualIncludeBybitOkx=!!checked;dualFuturesPage=1;loadDualFutures(true)}
function changeDualFuturesPage(change){dualFuturesPage=Math.max(1,dualFuturesPage+change);loadDualFutures(true)}
function selectDualFuturesPage(page){dualFuturesPage=Math.max(1,Number(page)||1);loadDualFutures(true)}
function renderDualFuturesShell(){const target=byId('dual-futures');target.innerHTML=`<div class="strategy-hero"><p class="eyebrow">STRATEGY 01 · FUTURES / FUTURES</p><h2>期多期空套利</h2><p>默认监控 Bybit → Binance 与 OKX → Binance；BY → OK 单独勾选后显示。做多交易所始终在左，做空交易所始终在右；趋势与涨跌幅统一参考 Binance 合约。</p><span class="mode-pill">后台每 5 秒更新 · 页面不闪烁</span></div><div class="panel"><div class="panel-title"><div><p class="eyebrow">LIVE FUTURES / FUTURES SCANNER</p><h2>期多期空机会</h2></div><div class="spot-actions"><label class="filter-check"><input id="dualIncludeBybitOkx" type="checkbox" onchange="setDualIncludeBybitOkx(this.checked)">显示 BY 对 OK</label><div class="search-suggest-wrap"><label class="search-control"><span>⌕</span><input id="dualFuturesSearch" type="search" autocomplete="off" placeholder="搜索币种，例如 BTC" oninput="setDualFuturesSearch(this.value)"></label><div id="dualFuturesSuggestions" class="symbol-suggestions hidden"></div></div><button onclick="loadDualFutures(true)">↻ 刷新数据</button></div></div><div class="table-wrap"><table class="dual-redesign-table"><thead><tr><th>交易对 / 趋势</th><th><div class="change-header"><span>涨跌幅</span><div class="change-sort-controls"><button class="dual-sort-header" data-dual-sort="binance_change_5m" onclick="setDualSort('binance_change_5m')">5MIN</button><button class="dual-sort-header" data-dual-sort="binance_change_15m" onclick="setDualSort('binance_change_15m')">15MIN</button><button class="dual-sort-header" data-dual-sort="binance_change_30m" onclick="setDualSort('binance_change_30m')">30MIN</button><button class="dual-sort-header" data-dual-sort="binance_change_1h" onclick="setDualSort('binance_change_1h')">1H</button><button class="dual-sort-header" data-dual-sort="binance_change_12h" onclick="setDualSort('binance_change_12h')">12H</button><button class="dual-sort-header" data-dual-sort="binance_change_24h" onclick="setDualSort('binance_change_24h')">24H</button><button class="dual-sort-header" data-dual-sort="binance_change_3d" onclick="setDualSort('binance_change_3d')">3D</button><button class="dual-sort-header" data-dual-sort="binance_change_7d" onclick="setDualSort('binance_change_7d')">7D</button></div></div></th><th>做多交易所</th><th>做空交易所</th><th><div class="dual-result-header"><span>套利结果 / 排序</span><div class="dual-result-sort-controls"><button class="dual-sort-header" data-dual-sort="open_spread" onclick="setDualSort('open_spread')">开差 ↓</button><button class="dual-sort-header" data-dual-sort="close_spread" onclick="setDualSort('close_spread')">平差</button><button class="dual-sort-header" data-dual-sort="funding_difference" onclick="setDualSort('funding_difference')">资费差</button><button class="dual-sort-header" data-dual-sort="binance_basis" onclick="setDualSort('binance_basis')">合约基差</button></div></div></th></tr></thead><tbody id="dualFuturesRows"><tr><td colspan="5" class="loading">正在连接三家交易所的公开合约行情…</td></tr></tbody></table></div><div class="pagination"><button id="dualPreviousPage" onclick="changeDualFuturesPage(-1)">← 上一页</button><label class="page-picker">跳至 <select id="dualFuturesPageSelect" onchange="selectDualFuturesPage(this.value)"></select> 页</label><span id="dualPageInfo">第 1 页</span><button id="dualNextPage" onclick="changeDualFuturesPage(1)">下一页 →</button></div><p class="data-status"><span id="dualFuturesUpdated"></span><span id="dualFuturesCountdown" class="refresh-countdown"></span></p></div>`}
async function loadDualFutures(manual=false){if(dualFuturesLoading||!byId('dualFuturesRows'))return;dualFuturesLoading=true;const status=byId('dualFuturesUpdated'),emptyColspan=byId('dual-futures')?.querySelector('.dual-redesign-table')?5:10;if(manual)status.textContent='正在读取后台已缓存的合约行情…';try{const response=await fetch('/api/dual-futures?page='+dualFuturesPage+'&symbol='+encodeURIComponent(dualFuturesSearch)+'&sort_by='+dualSort.key+'&sort_direction='+dualSort.direction+'&include_bybit_okx='+(dualIncludeBybitOkx?1:0));const data=await response.json();if(!response.ok)throw new Error(data.error||'期多期空行情暂时无法读取');destroyFloatingPopup();dualBasisOpenings=Object.fromEntries(data.symbols.map(group=>[group.symbol,group.basis_opening]));dualIndexRows=new Map();data.symbols.forEach(group=>group.rows.forEach(row=>{row._commonIndexId=`${group.symbol}|${row.long_exchange}|${row.short_exchange}`;dualIndexRows.set(row._commonIndexId,row)}));byId('dualFuturesRows').innerHTML=data.symbols.length?dualRows(data.symbols):`<tr><td colspan="${emptyColspan}" class="loading">没有符合条件的合约路径。</td></tr>`;dualFuturesHasData=true;updateDualSortHeaders();byId('dualPageInfo').textContent=`第 ${data.page} / ${data.pages} 页 · 共 ${data.total_symbols} 个币种`;const pageSelect=byId('dualFuturesPageSelect');pageSelect.innerHTML=Array.from({length:data.pages},(_,index)=>`<option value="${index+1}" ${index+1===data.page?'selected':''}>${index+1}</option>`).join('');byId('dualPreviousPage').disabled=data.page<=1;byId('dualNextPage').disabled=data.page>=data.pages;const byOkNote=data.include_bybit_okx?'含 BY→OK':'已过滤 BY→OK';status.textContent=`最近更新 ${data.updated_at} · ${byOkNote} · 已对全部 ${data.total_symbols} 个币种排序 · 当前按 ${dualSort.key} 排序`;showDualRefreshCountdown(data.next_refresh_in_seconds)}catch(error){if(!dualFuturesHasData)byId('dualFuturesRows').innerHTML=`<tr><td colspan="${emptyColspan}" class="loading">${error.message}</td></tr>`;status.textContent=dualFuturesHasData?'本次更新失败，已保留上一组有效数据。':error.message}finally{dualFuturesLoading=false}}
function addDualLiquidityHeader(){const table=byId('dual-futures')?.querySelector('table');if(!table||table.classList.contains('dual-redesign-table'))return;const header=table.querySelector('thead tr');const changeHeader=header?.querySelector('.change-header')?.closest('th');if(changeHeader&&!header.querySelector('.liquidity-column')){const column=document.createElement('th');column.className='liquidity-column';column.textContent='流动性';changeHeader.insertAdjacentElement('afterend',column)}table.querySelectorAll('td[colspan="8"]').forEach(cell=>cell.colSpan=9)}
function addDualBasisSortControls(){const button=byId('dual-futures')?.querySelector('[data-dual-sort="binance_basis"]');if(!button||button.closest('.basis-sort-controls'))return;const wrapper=document.createElement('div');wrapper.className='basis-sort-controls';wrapper.innerHTML='<span>合约基差</span><div><button class="dual-sort-header" data-dual-sort="binance_basis" onclick="setDualSort(\'binance_basis\')">BN</button><button class="dual-sort-header" data-dual-sort="bybit_basis" onclick="setDualSort(\'bybit_basis\')">BY</button><button class="dual-sort-header" data-dual-sort="okx_basis" onclick="setDualSort(\'okx_basis\')">OK</button></div>';button.replaceWith(wrapper)}
function alertLabel(type){return type==='futures_pump'?'合约拉升':type==='spot_pump'?'现货拉升':type==='rapid_spread'?'开差速变':type==='rapid_basis'?'基差速变':type==='dual_spread_threshold'?'开差异动':type==='dual_basis_threshold'?'BN 基差异动':'基差异动'}
function alertClass(type){return type==='futures_pump'?'futures':type==='spot_pump'?'spot':type==='rapid_spread'?'rapid-spread':type==='rapid_basis'?'rapid-basis':'basis'}
function alertMetric(value){return value===null||value===undefined?'—':percent(value)}
function strategyLabel(strategy){return strategy==='futures_futures'?'期多期空':'现多期空'}
function alertExchangeLeg(exchange,market,interval){return `<span>${exchangeName(exchange)} ${market}${interval?` <em class="interval-badge ${intervalClass(interval)}">${interval}H</em>`:''}</span>`}
function alertExchangePair(item){return `<div class="alert-exchange-pair">${alertExchangeLeg(item.long_exchange,item.long_market,item.long_interval)}<b>→</b>${alertExchangeLeg(item.short_exchange,item.short_market,item.short_interval)}</div>`}
function toggleTips(){byId('tipsPanel').classList.toggle('collapsed')}
function updateSoundControls(){const alarm=byId('alarmSoundToggle'),chat=byId('chatSoundToggle');if(alarm)alarm.checked=alarmSoundEnabled;if(chat)chat.checked=chatSoundEnabled}
async function playSignalSound(enabled,force=false){if(!force&&!enabled)return;try{alarmAudioContext=alarmAudioContext||new (window.AudioContext||window.webkitAudioContext)();if(alarmAudioContext.state==='suspended')await alarmAudioContext.resume();Array.from({length:12},(_,index)=>index*.125).forEach((offset,index)=>{const oscillator=alarmAudioContext.createOscillator(),gain=alarmAudioContext.createGain();oscillator.type='square';oscillator.frequency.value=index%2?880:1175;gain.gain.setValueAtTime(.0001,alarmAudioContext.currentTime+offset);gain.gain.exponentialRampToValueAtTime(.55,alarmAudioContext.currentTime+offset+.01);gain.gain.exponentialRampToValueAtTime(.0001,alarmAudioContext.currentTime+offset+.105);oscillator.connect(gain).connect(alarmAudioContext.destination);oscillator.start(alarmAudioContext.currentTime+offset);oscillator.stop(alarmAudioContext.currentTime+offset+.11)})}catch(error){}}
function playAlarmSound(force=false){return playSignalSound(alarmSoundEnabled,force)}
async function playChatSound(force=false){if(!force&&!chatSoundEnabled)return;try{alarmAudioContext=alarmAudioContext||new (window.AudioContext||window.webkitAudioContext)();if(alarmAudioContext.state==='suspended')await alarmAudioContext.resume();[[0,659.25],[.18,783.99]].forEach(([offset,frequency])=>{const oscillator=alarmAudioContext.createOscillator(),gain=alarmAudioContext.createGain(),start=alarmAudioContext.currentTime+offset;oscillator.type='sine';oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.22,start+.018);gain.gain.exponentialRampToValueAtTime(.0001,start+.28);oscillator.connect(gain).connect(alarmAudioContext.destination);oscillator.start(start);oscillator.stop(start+.3)})}catch(error){}}
function toggleAlarmSound(enabled){alarmSoundEnabled=Boolean(enabled);localStorage.setItem('arbi-alarm-sound',alarmSoundEnabled?'on':'off');updateSoundControls();if(alarmSoundEnabled)playAlarmSound()}
function toggleChatSound(enabled){chatSoundEnabled=Boolean(enabled);localStorage.setItem('arbi-chat-sound',chatSoundEnabled?'on':'off');updateSoundControls();if(chatSoundEnabled)playChatSound()}
function testAlarmSound(){playSignalSound(true,true)}
function alertDeathMarkup(item){const expiresAt=Date.now()+Math.max(0,Number(item.remaining_seconds)||0)*1000;return `<small class="alert-death" data-alert-expires="${expiresAt}">${item.created_at} · 剩余 ${item.remaining_seconds}s</small>`}
function updateAlertCountdowns(){let expired=false;document.querySelectorAll('.alert-death').forEach(node=>{const remaining=Math.max(0,Math.ceil((Number(node.dataset.alertExpires)-Date.now())/1000));node.textContent=node.textContent.replace(/剩余 \d+s$/,`剩余 ${remaining}s`);if(remaining===0)expired=true});if(expired)loadAlerts(true)}
function startAlertCountdown(){clearInterval(alertCountdownTimer);updateAlertCountdowns();alertCountdownTimer=setInterval(updateAlertCountdowns,1000)}
function isAlertMuted(symbol){return mutedAlertSymbols.has(symbol)}
function alertMuteButton(symbol){const muted=isAlertMuted(symbol);return `<button class="alert-mute-toggle ${muted?'muted':''}" onclick="toggleAlertMute('${symbol}',event)">${muted?'取消静音':'静音'}</button>`}
function alertSpeakerButton(symbol){const muted=isAlertMuted(symbol);return `<button class="alert-speaker-toggle ${muted?'muted':''}" title="${muted?'取消静音':'静音'}" onclick="toggleAlertMute('${symbol}',event)" aria-label="${muted?'取消静音':'静音'}"><span>${muted?'🔇':'🔊'}</span></button>`}
function pruneAlertMutes(groups,activeEvents){const visible=new Set([...(groups||[]).map(group=>group.symbol),...(activeEvents||[]).map(item=>item.symbol)]);[...mutedAlertSymbols].forEach(symbol=>{if(!visible.has(symbol))mutedAlertSymbols.delete(symbol)})}
function toggleAlertMute(symbol,event){event?.stopPropagation();if(isAlertMuted(symbol))mutedAlertSymbols.delete(symbol);else mutedAlertSymbols.add(symbol);renderAlertMasterDetail(latestAlertGroups);renderAlertMuteList();renderTipsItems(latestActiveAlertEvents)}
function renderAlertMuteList(){const target=byId('alertMuteList');if(!target)return;const muted=[...mutedAlertSymbols].sort();target.innerHTML=muted.length?muted.map(symbol=>`<button class="muted-symbol-pill" onclick="toggleAlertMute('${symbol}',event)">${symbol}<span>取消</span></button>`).join(''):'<p class="empty-alert">暂无静音币种。</p>'}
function alertTimelineNode(item){return `<li class="alert-timeline-node ${alertClass(item.type)}"><i></i><div><time>${item.created_at}</time><b>${strategyLabel(item.strategy)} · ${alertLabel(item.type)}</b>${alertExchangePair(item)}<span>开差 <em class="${changeClass(item.open_spread)}">${alertMetric(item.open_spread)}</em> · 基差 <em class="${changeClass(item.basis)}">${alertMetric(item.basis)}</em></span></div></li>`}
function alertDetailCard(group){const latest=group.latest;return `<article class="alert-detail-card ${alertClass(latest.type)} ${isAlertMuted(group.symbol)?'muted-alert':''}"><header><div><div class="alert-card-title"><h4>${group.symbol}</h4><span class="strategy-badge">${group.alert_count} 次报警${isAlertMuted(group.symbol)?' · 已静音':''}</span></div><span class="alert-latest-label">最近：${strategyLabel(latest.strategy)} · ${alertLabel(latest.type)} · ${latest.created_at}</span></div><div class="alert-values"><span>开差 <b class="${changeClass(latest.open_spread)}">${alertMetric(latest.open_spread)}</b></span><span>基差 <b class="${changeClass(latest.basis)}">${alertMetric(latest.basis)}</b></span></div></header>${alertExchangePair(latest)}<ol class="alert-timeline">${group.timeline.map(alertTimelineNode).join('')}</ol></article>`}
function alertMovePeaks(group){const peaks=group.move_peaks||{};return `<div class="alert-move-peaks"><span>开差峰值 <b class="${changeClass(peaks.open_spread)}">${alertMetric(peaks.open_spread)}</b></span><span>基差峰值 <b class="${changeClass(peaks.basis)}">${alertMetric(peaks.basis)}</b></span></div>`}
function renderAlertMasterDetail(groups){latestAlertGroups=groups;if(!groups.some(group=>group.symbol===selectedAlertSymbol))selectedAlertSymbol=groups[0]?.symbol||'';const selected=groups.find(group=>group.symbol===selectedAlertSymbol);byId('alertEvents').innerHTML=groups.length?`<div class="alert-symbol-list">${groups.map(group=>{const latest=group.latest;return `<button class="alert-symbol-option ${group.symbol===selectedAlertSymbol?'active':''} ${alertClass(latest.type)}" onclick="selectAlertSymbol('${group.symbol}')"><b>${group.symbol}</b><span>${latest.created_at} · ${alertLabel(latest.type)}</span>${alertMovePeaks(group)}<small>${group.alert_count} 次 · 最近开差 ${alertMetric(latest.open_spread)} · 最近基差 ${alertMetric(latest.basis)}</small></button>`}).join('')}</div><div class="alert-detail-pane">${alertDetailCard(selected)}</div>`:'<p class="empty-alert">暂时没有确认后的报警。</p>'}
function alertSymbolCard(group){const latest=group.latest;return `<article class="alert-symbol-option ${group.symbol===selectedAlertSymbol?'active':''} ${alertClass(latest.type)} ${isAlertMuted(group.symbol)?'muted-alert':''}" onclick="selectAlertSymbol('${group.symbol}')"><div class="alert-symbol-top"><b>${group.symbol}</b><em>${group.alert_count}次${isAlertMuted(group.symbol)?' · 静音':''}</em></div><div class="alert-symbol-meta"><span>${latest.created_at}</span><strong>${strategyLabel(latest.strategy)} · ${alertLabel(latest.type)}</strong></div>${alertMuteButton(group.symbol)}${alertMovePeaks(group)}<div class="alert-latest-metrics"><span>最近开差 <b class="${changeClass(latest.open_spread)}">${alertMetric(latest.open_spread)}</b></span><span>最近基差 <b class="${changeClass(latest.basis)}">${alertMetric(latest.basis)}</b></span></div></article>`}
function renderAlertMasterDetail(groups){latestAlertGroups=groups;if(!groups.some(group=>group.symbol===selectedAlertSymbol))selectedAlertSymbol=groups[0]?.symbol||'';const selected=groups.find(group=>group.symbol===selectedAlertSymbol);byId('alertEvents').innerHTML=groups.length?`<div class="alert-symbol-list">${groups.map(alertSymbolCard).join('')}</div><div class="alert-detail-pane">${alertDetailCard(selected)}</div>`:'<p class="empty-alert">暂时没有确认后的报警。</p>'}
function selectAlertSymbol(symbol){selectedAlertSymbol=symbol;renderAlertMasterDetail(latestAlertGroups)}
function renderTipsItems(activeEvents){const target=byId('tipsItems');if(!target)return;target.innerHTML=activeEvents.length?activeEvents.map(item=>`<article class="tips-item ${alertClass(item.type)} ${isAlertMuted(item.symbol)?'muted-alert':''}"><div class="tips-item-head"><b>${item.symbol} · ${strategyLabel(item.strategy)} · ${alertLabel(item.type)}${isAlertMuted(item.symbol)?' · 已静音':''}</b>${alertSpeakerButton(item.symbol)}</div>${alertExchangePair(item)}<span>开差 ${alertMetric(item.open_spread)} · 基差 ${alertMetric(item.basis)}</span>${alertDeathMarkup(item)}</article>`).join(''):'<p class="empty-alert">当前没有处于 120 秒有效期的报警。</p>'}
async function loadAlerts(force=false){try{const data=await (await fetch('/api/alerts')).json(),activeEvents=data.active_events||[],groups=data.events||[];pruneAlertMutes(groups,activeEvents);latestActiveAlertEvents=activeEvents;const signature=activeEvents.map(item=>`${item.symbol}-${item.type}-${item.open_spread}-${item.basis}-${item.created_at}`).join('|'),audibleSignature=activeEvents.filter(item=>!isAlertMuted(item.symbol)).map(item=>`${item.symbol}-${item.type}-${item.open_spread}-${item.basis}-${item.created_at}`).join('|');const hasNewAlert=alertsInitialized&&audibleSignature!==alertAudibleSignature&&audibleSignature.length>0;if(!force&&signature===alertSignature)return;alertSignature=signature;alertAudibleSignature=audibleSignature;renderAlertMasterDetail(groups);byId('basisTracking').innerHTML=data.basis_tracking.length?data.basis_tracking.map(item=>`<article class="alert-item basis"><div class="alert-card-title"><h4>${item.symbol}</h4><span class="strategy-badge">${strategyLabel(item.strategy)} · 基差追踪</span></div><p class="tracking-max">最大 ${percent(item.max_basis)}</p><div class="meta"><span>已记录至 ${item.last_level.toFixed(1)}%</span><span>最大时间 ${item.max_at}</span></div></article>`).join(''):'<p class="empty-alert">暂无正在追踪的基差扩展。</p>';renderAlertMuteList();byId('tipsCount').textContent=activeEvents.length;renderTipsItems(activeEvents);startAlertCountdown();alertsInitialized=true;if(hasNewAlert)playAlarmSound()}catch(error){byId('alertEvents').innerHTML='<p class="empty-alert">报警记录暂时无法读取。</p>';byId('tipsItems').innerHTML='<p class="empty-alert">报警暂时无法读取。</p>'}}
function tokenHedgeList(items){return `<ul>${(items||[]).map(item=>`<li>${item}</li>`).join('')}</ul>`}
function tokenHedgeSources(items){return `<div class="token-hedge-sources">${(items||[]).map(item=>`<a target="_blank" rel="noopener noreferrer" href="${item.url}">${item.label}</a>`).join('')}</div>`}
async function loadTokenHedgeProfiles(){const target=byId('tokenHedgeProfiles');if(!target)return;target.innerHTML='<p class="loading">正在读取代币档案…</p>';try{const data=await (await fetch('/api/token-hedge/profiles')).json();target.innerHTML=data.profiles?.length?data.profiles.map(item=>`<article class="token-hedge-card ${item.risk_level==='极高'?'extreme':'high'}"><div class="token-hedge-head"><div><p class="eyebrow">${item.status}</p><h3>${item.symbol}<span>${item.name}</span></h3></div><b>${item.risk_level}</b></div><section><h4>官方已确认</h4>${tokenHedgeList(item.official_facts)}</section><section class="token-hedge-thesis"><h4>盘口推演</h4><p>${item.market_thesis}</p></section><section><h4>盯盘规则</h4>${tokenHedgeList(item.watch_rules)}</section>${tokenHedgeSources(item.sources)}</article>`).join(''):'<p class="empty-alert">暂无代币档案。</p>'}catch(error){target.innerHTML='<p class="empty-alert">代币档案暂时无法读取。</p>'}}
function isDailyView(viewId){return ['daily-trends','daily-thoughts','daily-listings'].includes(viewId)}
function updateSidebarSubnav(viewId){document.querySelectorAll('aside .nav-sub').forEach(item=>item.classList.add('hidden'));document.querySelectorAll('aside nav a[data-subnav]').forEach(item=>item.classList.remove('expanded'));if(viewId==='spot-futures'){document.querySelector('aside .spot-period-nav')?.classList.remove('hidden');document.querySelector('aside nav a[data-subnav="spot-period-nav"]')?.classList.add('expanded')}if(isDailyView(viewId)){document.querySelector('aside .daily-nav')?.classList.remove('hidden');document.querySelector('aside nav a[data-subnav="daily-nav"]')?.classList.add('expanded')}}
function updateSidebarActive(link,viewId){document.querySelectorAll('nav a[data-view]').forEach(item=>{const parentSpot=item.dataset.subnav==='spot-period-nav'&&viewId==='spot-futures';const parentDaily=item.dataset.subnav==='daily-nav'&&isDailyView(viewId);item.classList.toggle('active',item===link||parentSpot||parentDaily)})}
function updateChatNavAttention(){const entry=document.querySelector('aside .chat-nav-entry'),chatActive=byId('chat')?.classList.contains('active');entry?.classList.toggle('chat-attention',chatNavAttentionPending&&!chatActive)}
function acknowledgeChatNavAttention(){chatNavAttentionPending=false;updateChatNavAttention()}
document.querySelectorAll('nav a[data-view]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();const viewId=link.dataset.view;document.querySelectorAll('.view').forEach(view=>view.classList.toggle('active',view.id===viewId));updateSidebarActive(link,viewId);updateSidebarSubnav(viewId);if(viewId==='dashboard')loadDashboard();if(viewId==='spot-futures')loadSpotFutures();if(viewId==='dual-futures')loadDualFutures();if(viewId==='thinking')loadSimpleThinking();if(viewId==='strategies')loadStrategies();if(viewId==='alerts')loadAlerts(true);if(viewId==='chat'){acknowledgeChatNavAttention();loadChat(true)}if(viewId==='daily-trends')loadDailyTrends();if(viewId==='daily-thoughts')loadThoughtAnalysis();if(viewId==='daily-listings')loadDailyListings();if(viewId==='token-hedge')loadTokenHedgeProfiles();if(viewId==='funding-trend')loadFundingTrend();if(viewId==='trade-validation')loadTradeValidation();if(viewId==='runtime-rules')loadRuntimeRules();if(viewId==='account-management')loadAccountManagement();window.location.hash=viewId}));

function applyAdminUi(){document.querySelectorAll('.admin-write-only').forEach(node=>node.classList.toggle('hidden',!authState.is_admin))}
function applyChatNavVisibility(){document.querySelector('aside .chat-nav-entry')?.classList.toggle('hidden',Boolean(authState.chat_nav_hidden))}
async function loadAuthState(){try{const response=await fetch('/api/auth/me');if(response.status===401){location.href='/login';return}authState=await response.json();applyAdminUi();applyChatNavVisibility()}catch(error){}}
async function logoutAccount(){try{await fetch('/api/auth/logout',{method:'POST'})}finally{location.href='/login'}}
function ruleScheduleText(item){if(item.schedule_type==='toggle')return String(item.value)==='1'?'已隐藏':'正常显示';if(item.schedule_type==='daily_time')return `每天 ${item.value}`;if(item.schedule_type==='policy')return item.value;if(item.schedule_type==='retention')return `${item.value} ${item.unit}`;const seconds=Number(item.value);if(seconds>=3600&&seconds%3600===0)return `每 ${seconds/3600} 小时`;if(seconds>=60&&seconds%60===0)return `每 ${seconds/60} 分钟`;return `每 ${item.value} ${item.unit}`}
function ruleStatusMarkup(item){if(item.account_scoped)return '<small>仅作用于当前登录账号</small>';const status=item.automation;if(!status)return '<small>运行中</small>';if(status.last_error)return `<small class="rule-error">最近失败：${status.last_error_at||'—'} · ${status.last_error}</small>`;return `<small>最近成功：${status.last_success_at||'等待首次执行'}</small>`}
function openChatWorkspace(){const link=document.querySelector('aside a[data-view="chat"]');document.querySelectorAll('.view').forEach(view=>view.classList.toggle('active',view.id==='chat'));updateSidebarActive(link,'chat');updateSidebarSubnav('chat');acknowledgeChatNavAttention();window.location.hash='chat';loadChat(true)}
function ruleCard(item){const toggle=item.schedule_type==='toggle',input=toggle?`<label class="rule-toggle"><input data-rule-value="${item.key}" type="checkbox" ${String(item.value)==='1'?'checked':''}><span>隐藏左侧入口</span></label>`:`<input data-rule-value="${item.key}" value="${item.value}" ${item.schedule_type==='daily_time'?'type="time"':'type="number"'} ${item.min_value!=null?`min="${item.min_value}"`:''} ${item.max_value!=null?`max="${item.max_value}"`:''}>`,edit=authState.is_admin&&item.editable?`<div class="rule-editor">${input}<button onclick="saveRuntimeRule('${item.key}')">保存</button></div>`:'',open=item.key==='chat_nav_hidden'?'<button class="rule-open-private" onclick="openChatWorkspace()">打开协作记录</button>':'';return `<article class="runtime-rule-card ${item.editable?'editable':'locked'}"><div class="rule-card-head"><span>${item.label}</span><b>${ruleScheduleText(item)}</b></div><p>${item.description}</p>${ruleStatusMarkup(item)}${edit}${open}</article>`}
async function loadRuntimeRules(){const target=byId('runtimeRules');if(!target)return;target.classList.add('soft-loading');try{await loadAuthState();const data=await (await fetch('/api/runtime-rules')).json(),groups={};data.items.forEach(item=>(groups[item.category]??=[]).push(item));target.innerHTML=Object.entries(groups).map(([category,items])=>`<section class="runtime-rule-group"><h3>${category}</h3><div>${items.map(ruleCard).join('')}</div></section>`).join('');byId('runtimeRuleSummary').innerHTML=`<article><b>${data.items.length}</b><span>条运行与知识规则</span></article><article><b>${data.items.filter(item=>item.editable).length}</b><span>条规则可管理</span></article><article><b>${data.is_admin?'管理员':'只读'}</b><span>当前权限</span></article>`;byId('adminInvitePanel')?.classList.toggle('hidden',!data.is_admin);if(data.is_admin)loadInviteHistory()}catch(error){target.innerHTML='<p class="empty-alert">运行规则暂时无法读取。</p>'}finally{target.classList.remove('soft-loading')}}
async function saveRuntimeRule(key){const input=document.querySelector(`[data-rule-value="${key}"]`),value=input.type==='checkbox'?(input.checked?'1':'0'):input.value,response=await fetch(`/api/runtime-rules/${key}`,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({value,enabled:true})}),data=await response.json();if(!response.ok){alert(data.error||'保存失败');return}await loadAuthState();await loadRuntimeRules();startConfiguredPageTimers()}
async function createInviteCode(){const response=await fetch('/api/admin/invites',{method:'POST',headers:{'X-CSRF-Token':authState.csrf_token}}),data=await response.json();if(!response.ok){alert(data.error||'生成失败');return}const target=byId('newInviteCode');target.classList.remove('hidden');target.innerHTML=`<span>新邀请码（只显示这一次）</span><b>${data.code}</b><button onclick="navigator.clipboard.writeText('${data.code}')">复制</button><small>有效至 ${data.expires_at}</small>`;loadInviteHistory()}
async function loadInviteHistory(){const target=byId('inviteHistory');if(!target)return;const data=await (await fetch('/api/admin/invites')).json();target.innerHTML=data.items?.length?data.items.map(item=>`<span><b>${item.prefix}…</b><em class="${item.used?'used':''}">${item.used?'已使用':'等待使用'}</em><small>${item.expires_at||'长期有效'}</small></span>`).join(''):'<p class="empty-alert">还没有生成邀请码。</p>'}
function accountInviteStatus(item){if(item.status==='used')return ['已使用','used'];if(item.status==='expired')return ['已过期','expired'];return ['可使用','available']}
function accountInviteMarkup(item){const [label,state]=accountInviteStatus(item),shown=item.code||`${item.prefix}…`,copy=item.code?`<button onclick="navigator.clipboard.writeText('${item.code}')">复制</button>`:'',usage=item.used_by?`注册账号 <b>${item.used_by}</b> · ${item.used_at}`:(state==='available'?(item.code?'尚未注册':'历史邀请码仅保留前缀，请生成新码后使用'):`未使用 · ${item.expires_at||'—'}`);return `<article class="account-invite-item ${state}"><div class="account-invite-code"><code>${shown}</code><span>${label}</span>${copy}</div><p>${usage}</p><small>生成 ${item.created_at} · 有效至 ${item.expires_at||'长期有效'}</small></article>`}
function accountUserMarkup(item){const username=escapeChatHtml(item.username);return `<article class="account-user-item"><div><span class="account-avatar">${username.slice(0,1).toUpperCase()}</span><p><b>${username}</b><small>${item.role==='admin'?'管理员':'普通查看账号'}</small></p><em class="${item.active?'active':'disabled'}">${item.active?'可登录':'已停用'}</em></div><dl><div><dt>注册时间</dt><dd>${item.created_at||'—'}</dd></div><div><dt>最近登录</dt><dd>${item.last_login_at||'尚未登录'}</dd></div><div><dt>密码更新</dt><dd id="accountPasswordChanged${item.id}">${item.password_changed_at||'尚未重置'}</dd></div></dl><div class="account-security-actions"><button type="button" onclick="toggleAccountPasswordReset(${item.id})">重置密码</button><small>密码不可查看，只能安全重置</small></div><div id="accountPasswordReset${item.id}" class="account-password-reset hidden"><label>设置新密码<input id="accountNewPassword${item.id}" type="password" minlength="10" maxlength="128" autocomplete="new-password" placeholder="至少 10 位"></label><div><button type="button" onclick="resetAccountPassword(${item.id},'custom')">保存新密码</button><button type="button" onclick="resetAccountPassword(${item.id},'generate')">生成临时密码</button></div><p id="accountPasswordResult${item.id}"></p></div></article>`}
function toggleAccountPasswordReset(userId){byId(`accountPasswordReset${userId}`)?.classList.toggle('hidden')}
function showAccountPasswordResult(userId,data){const target=byId(`accountPasswordResult${userId}`);if(!target)return;target.innerHTML='';if(data.temporary_password){const label=document.createElement('span');label.textContent='一次性显示，请立即交给该账号：';const code=document.createElement('code');code.textContent=data.temporary_password;const copy=document.createElement('button');copy.type='button';copy.textContent='复制';copy.onclick=()=>navigator.clipboard.writeText(data.temporary_password);target.append(label,code,copy)}else{target.textContent='新密码已保存，原登录设备已退出。'}const changed=byId(`accountPasswordChanged${userId}`);if(changed)changed.textContent=data.password_changed_at||'刚刚'}
async function resetAccountPassword(userId,mode){const input=byId(`accountNewPassword${userId}`),newPassword=input?.value||'';if(mode==='custom'&&newPassword.length<10){alert('新密码至少需要 10 位。');input?.focus();return}const wording=mode==='generate'?'生成新的临时密码':'保存这个新密码';if(!confirm(`${wording}后，该账号当前登录设备会立即退出。确定继续吗？`))return;const response=await fetch(`/api/admin/users/${userId}/password`,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify(mode==='generate'?{mode:'generate'}:{new_password:newPassword})}),data=await response.json();if(!response.ok){alert(data.error||'密码重置失败');return}if(input)input.value='';showAccountPasswordResult(userId,data);if(Number(userId)===Number(authState.user_id)){alert('你的管理员密码已经更新，请使用新密码重新登录。');location.href='/login'}}
async function loadAccountManagement(){const summary=byId('accountSummary'),inviteTarget=byId('accountInviteList'),userTarget=byId('accountUserList');if(!summary||!inviteTarget||!userTarget)return;summary.classList.add('soft-loading');try{await loadAuthState();const [inviteResponse,userResponse]=await Promise.all([fetch('/api/admin/invites'),fetch('/api/admin/users')]);const invites=await inviteResponse.json(),users=await userResponse.json();if(!inviteResponse.ok||!userResponse.ok)throw new Error(invites.error||users.error||'账号数据读取失败');const available=invites.items.filter(item=>item.status==='available'&&item.code).length,used=invites.items.filter(item=>item.status==='used').length;summary.innerHTML=`<article><b>${users.items.length}</b><span>全部账号</span></article><article><b>${available}</b><span>可用邀请码</span></article><article><b>${used}</b><span>已注册使用</span></article>`;inviteTarget.innerHTML=invites.items.length?invites.items.map(accountInviteMarkup).join(''):'<p class="empty-alert">还没有邀请码，点击右上角生成第一个。</p>';userTarget.innerHTML=users.items.length?users.items.map(accountUserMarkup).join(''):'<p class="empty-alert">还没有账号记录。</p>'}catch(error){summary.innerHTML=`<p class="empty-alert">${error.message}</p>`;inviteTarget.innerHTML='';userTarget.innerHTML=''}finally{summary.classList.remove('soft-loading')}}
async function createAccountInviteCode(){await loadAuthState();const response=await fetch('/api/admin/invites',{method:'POST',headers:{'X-CSRF-Token':authState.csrf_token}}),data=await response.json();if(!response.ok){alert(data.error||'生成失败');return}const target=byId('accountNewInvite');target.classList.remove('hidden');target.innerHTML=`<span>新邀请码</span><b>${data.code}</b><button onclick="navigator.clipboard.writeText('${data.code}')">复制</button><small>仅能注册一次 · 有效至 ${data.expires_at}</small>`;await loadAccountManagement()}

function escapeChatHtml(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function isChatNetworkError(error){return error instanceof TypeError||/failed to fetch|networkerror|load failed|network request failed/i.test(String(error?.message||error||''))}
function chatRetryDelay(milliseconds){return new Promise(resolve=>setTimeout(resolve,milliseconds))}
function showChatNetworkStatus(text='网络短暂波动，正在自动恢复…'){const status=byId('chatSendStatus');if(!status||chatSendInFlight)return;status.dataset.networkStatus='1';status.textContent=text}
function clearChatNetworkStatus(){const status=byId('chatSendStatus');if(!status||status.dataset.networkStatus!=='1')return;delete status.dataset.networkStatus;status.textContent='内容仅在登录账号间可见 · 最多保留 30 天'}
async function chatFetch(url,options={},retries=2){let lastError;for(let attempt=0;attempt<=retries;attempt+=1){try{return await fetch(url,options)}catch(error){lastError=error;if(!isChatNetworkError(error)||attempt>=retries)throw error;showChatNetworkStatus();await chatRetryDelay(350*(attempt+1))}}throw lastError}
function handleChatBackgroundError(error){if(isChatNetworkError(error))showChatNetworkStatus()}
function chatDisplayName(item){return String(item?.remark||item?.display_name||item?.username||'')}
function chatPeerMarkup(item){const preview=item.last_message?escapeChatHtml(item.last_message):'还没有消息',badge=item.unread?`<em>${item.unread>99?'99+':item.unread}</em>`:'',displayName=escapeChatHtml(chatDisplayName(item)),accountPrefix=item.remark?`账号 ${escapeChatHtml(item.username)} · `:'';return `<div class="chat-peer ${item.id===chatPeerId?'active':''}" role="button" tabindex="0" onclick="selectChatPeer(${item.id})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();selectChatPeer(${item.id})}"><button type="button" class="chat-avatar chat-avatar-edit" onclick="openChatRemarkEditor(${item.id},event)" title="修改 ${escapeChatHtml(item.username)} 的备注" aria-label="修改 ${escapeChatHtml(item.username)} 的备注">${escapeChatHtml(item.username.slice(0,1).toUpperCase())}<span class="chat-avatar-edit-mark">✎</span></button><span class="chat-peer-copy"><b>${displayName} ${item.online?'<i>在线</i>':''}</b><small>${accountPrefix}${preview}</small></span><span class="chat-peer-meta"><time>${item.last_message_at||''}</time>${badge}</span></div>`}
function filteredChatUsers(){return chatUsers.filter(item=>!chatPeerQuery||item.username.toLowerCase().includes(chatPeerQuery)||chatDisplayName(item).toLowerCase().includes(chatPeerQuery))}
function newestChatMessageId(items,predicate=()=>true){return Math.max(0,...(items||[]).filter(predicate).map(item=>Number(item.last_message_id??item.id)||0))}
function announceIncomingChatMessage(messageId){const id=Number(messageId)||0;if(!id||id<=chatLastNotifiedIncomingId)return;chatLastNotifiedIncomingId=id;if(!byId('chat')?.classList.contains('active'))chatNavAttentionPending=true;updateChatNavAttention();playChatSound()}
function observeIncomingChatMessages(items,initial=false){const latest=newestChatMessageId(items,item=>Number(item.recipient_id)===Number(authState.user_id));if(!latest)return;if(initial||!chatUnreadInitialized){chatLastNotifiedIncomingId=Math.max(chatLastNotifiedIncomingId,latest);return}announceIncomingChatMessage(latest)}
function renderChatUsers(data,force=false){chatUsers=data.items||[];const total=Number(data.unread_total)||0,target=byId('chatPeerList'),latestAny=newestChatMessageId(chatUsers),latestUnread=newestChatMessageId(chatUsers,item=>Number(item.unread)>0);if(!chatUnreadInitialized){chatLastNotifiedIncomingId=Math.max(chatLastNotifiedIncomingId,latestAny);chatNavAttentionPending=total>0&&!byId('chat')?.classList.contains('active')}else if(latestUnread>chatLastNotifiedIncomingId){announceIncomingChatMessage(latestUnread)}chatUnreadTotal=total;chatUnreadInitialized=true;byId('chatUnreadSummary').textContent=`${total} 条未读`;updateChatNavAttention();const visible=filteredChatUsers(),signature=JSON.stringify([chatPeerId,chatPeerQuery,chatUsers.map(item=>[item.id,item.online,item.last_seen_at,item.last_message,item.last_message_at,item.last_message_id,item.unread,item.remark,item.display_name])]);if(!force&&signature===chatUsersSignature)return;chatUsersSignature=signature;target.innerHTML=visible.length?visible.map(chatPeerMarkup).join(''):(chatUsers.length?'<p class="chat-empty">没有匹配的账号。</p>':'<p class="chat-empty">目前没有其他可用账号。</p>')}
async function loadChatUsers(){
  if(chatUsersRequest)return chatUsersRequest;
  const task=(async()=>{const response=await chatFetch('/api/chat/users'),data=await response.json();if(!response.ok)throw new Error(data.error||'联系人读取失败');renderChatUsers(data);clearChatNetworkStatus();return data})();
  chatUsersRequest=task;
  try{return await task}finally{if(chatUsersRequest===task)chatUsersRequest=null}
}
function chatReceiptTitle(read,readAt){return read?`已读时间：${readAt||'历史时间未记录'}`:'对方尚未读取'}
function chatMessageMarkup(item){const mine=item.sender_id===authState.user_id,body=item.body?`<p>${escapeChatHtml(item.body).replace(/\n/g,'<br>')}</p>`:'',picture=item.image?`<a class="chat-message-image" href="${escapeChatHtml(item.image.url)}" target="_blank" rel="noopener" title="打开原图"><img src="${escapeChatHtml(item.image.url)}" alt="${escapeChatHtml(item.image.name||'聊天图片')}" loading="lazy"><span>${escapeChatHtml(item.image.name||'图片')} · ${chatFileSize(item.image.size)}</span></a>`:'',receiptTitle=chatReceiptTitle(item.read_by_peer,item.read_at),receipt=mine?`<span class="chat-read-state ${item.read_by_peer?'read':'unread'}" title="${escapeChatHtml(receiptTitle)}" aria-label="${escapeChatHtml(receiptTitle)}"><i aria-hidden="true"></i></span>`:'';return `<article class="chat-message ${mine?'mine':'theirs'}" data-message-id="${item.id}"><div>${picture}${body}<footer><small class="chat-message-time">${escapeChatHtml(item.created_at)}</small>${receipt}</footer></div></article>`}
function uniqueChatMessages(items){const unique=new Map();for(const item of items||[]){const id=Number(item?.id)||0;if(id)unique.set(id,item)}return [...unique.values()].sort((left,right)=>Number(left.id)-Number(right.id))}
function chatMessageIsRendered(id){return Boolean(byId('chatMessages')?.querySelector(`[data-message-id="${Number(id)}"]`))}
function updateChatReadReceipts(lastReadId,lastReadAt){const readThrough=Number(lastReadId)||0;document.querySelectorAll('#chatMessages .chat-message.mine[data-message-id]').forEach(node=>{const status=node.querySelector('.chat-read-state'),read=Number(node.dataset.messageId)<=readThrough;if(!status)return;const becameRead=read&&!status.classList.contains('read');status.classList.toggle('read',read);status.classList.toggle('unread',!read);if(becameRead||!read){const title=chatReceiptTitle(read,read?lastReadAt:null);status.title=title;status.setAttribute('aria-label',title)}})}
function appendNewChatMessages(rawItems,forceScroll=false){const target=byId('chatMessages');if(!target)return 0;const items=uniqueChatMessages(rawItems),nearBottom=target.scrollHeight-target.scrollTop-target.clientHeight<90,fresh=items.filter(item=>!chatMessageIsRendered(item.id));if(fresh.length){target.querySelector('.chat-empty')?.remove();target.insertAdjacentHTML('beforeend',fresh.map(chatMessageMarkup).join(''))}if(items.length){chatLastMessageId=Math.max(chatLastMessageId,...items.map(item=>Number(item.id)));if(!chatOldestMessageId)chatOldestMessageId=Math.min(...items.map(item=>Number(item.id)))}if(fresh.length&&(forceScroll||nearBottom))scrollChatToBottom();return fresh.length}
function chatFileSize(size){const value=Number(size)||0;return value>=1024*1024?`${(value/1024/1024).toFixed(1)}MB`:`${Math.max(1,Math.round(value/1024))}KB`}
function scrollChatToBottom(){const target=byId('chatMessages');requestAnimationFrame(()=>{target.scrollTop=target.scrollHeight})}
function chatPresenceText(peer){if(peer.online)return '在线';return peer.last_seen_at?`最近在线 ${peer.last_seen_at}`:'当前离线'}
function renderChatConversationHeader(peer){if(!peer||peer.id!==chatPeerId)return;const displayName=chatDisplayName(peer),account=peer.remark?`账号 ${peer.username} · `:'';byId('chatConversationHeader').innerHTML=`<div><b>${escapeChatHtml(displayName)}</b><small>${escapeChatHtml(account)}${peer.role==='admin'?'管理员':'普通账号'} · ${escapeChatHtml(chatPresenceText(peer))}</small></div><button class="chat-clear" onclick="clearMyChatHistory()">清空我的记录</button>`}
function openChatRemarkEditor(peerId,event){event?.stopPropagation();const peer=chatUsers.find(item=>Number(item.id)===Number(peerId));if(!peer)return;chatRemarkPeerId=Number(peerId);byId('chatRemarkAccount').textContent=`真实账号：${peer.username}`;const input=byId('chatRemarkInput');input.value=peer.remark||'';byId('chatRemarkModal').classList.remove('hidden');requestAnimationFrame(()=>{input.focus();input.select()})}
function closeChatRemarkEditor(){chatRemarkPeerId=0;byId('chatRemarkModal')?.classList.add('hidden')}
async function saveChatRemark(event,clear=false){event?.preventDefault();if(!chatRemarkPeerId)return;const input=byId('chatRemarkInput'),remark=clear?'':input.value.trim(),response=await fetch(`/api/chat/users/${chatRemarkPeerId}/remark`,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({remark})}),data=await response.json();if(!response.ok){alert(data.error||'备注保存失败');return}const peer=chatUsers.find(item=>Number(item.id)===Number(data.peer_id));if(peer){peer.remark=data.remark;peer.display_name=data.display_name}chatUsersSignature='';renderChatUsers({items:chatUsers,unread_total:chatUsers.reduce((sum,item)=>sum+Number(item.unread||0),0)},true);if(peer)renderChatConversationHeader(peer);closeChatRemarkEditor()}
function updateChatHistoryBar(){const bar=byId('chatHistoryBar');if(!bar)return;bar.classList.toggle('hidden',!chatPeerId||!chatHasMoreBefore);const button=bar.querySelector('button');if(button){button.disabled=false;button.textContent='加载更早消息'}}
async function selectChatPeer(peerId){chatPeerId=Number(peerId);chatLastMessageId=0;chatOldestMessageId=0;chatHasMoreBefore=false;chatUsersSignature='';clearChatImage();const peer=chatUsers.find(item=>item.id===chatPeerId);if(!peer)return;renderChatConversationHeader(peer);const input=byId('chatInput'),send=byId('chatComposer').querySelector('button[type="submit"]');input.disabled=false;send.disabled=false;byId('chatEmojiButton').disabled=false;byId('chatImageButton').disabled=false;byId('chatMessages').innerHTML='<p class="loading">正在读取消息…</p>';updateChatHistoryBar();renderChatUsers({items:chatUsers,unread_total:chatUsers.reduce((sum,item)=>sum+Number(item.unread||0),0)},true);try{await loadChatMessages('initial');await loadChatUsers()}catch(error){handleChatBackgroundError(error);byId('chatMessages').innerHTML=`<p class="chat-empty">${isChatNetworkError(error)?'网络刚刚闪断，正在自动恢复…':escapeChatHtml(error.message||'消息读取失败')}</p>`}startChatPolling();input.focus()}
async function loadChatMessages(mode='newer',forceScroll=false){
  const requestedPeerId=Number(chatPeerId);
  if(!requestedPeerId)return;
  let query='';
  if(mode==='newer'&&chatLastMessageId)query=`?after_id=${chatLastMessageId}`;
  if(mode==='older'&&chatOldestMessageId)query=`?before_id=${chatOldestMessageId}`;
  const requestKey=`${requestedPeerId}:${mode}:${query}`;
  if(chatMessageRequests.has(requestKey))return chatMessageRequests.get(requestKey);
  const task=(async()=>{
    const target=byId('chatMessages'),oldHeight=target.scrollHeight,oldTop=target.scrollTop;
    const response=await chatFetch(`/api/chat/messages/${requestedPeerId}${query}`),data=await response.json();
    if(!response.ok)throw new Error(data.error||'消息读取失败');
    if(Number(chatPeerId)!==requestedPeerId)return data;
    const items=uniqueChatMessages(data.items||[]);
    if(mode==='initial'||(!chatLastMessageId&&mode!=='older')){
      observeIncomingChatMessages(items,true);
      target.innerHTML=items.length?items.map(chatMessageMarkup).join(''):'<p class="chat-empty">你这边还没有保留的聊天记录。</p>';
      chatOldestMessageId=items[0]?.id||0;
      chatLastMessageId=items[items.length-1]?.id||0;
      chatHasMoreBefore=Boolean(data.has_more_before);
      scrollChatToBottom();
    }else if(mode==='older'){
      const fresh=items.filter(item=>!chatMessageIsRendered(item.id));
      if(fresh.length){target.querySelector('.chat-empty')?.remove();target.insertAdjacentHTML('afterbegin',fresh.map(chatMessageMarkup).join(''));chatOldestMessageId=Math.min(chatOldestMessageId||Infinity,...items.map(item=>Number(item.id)));requestAnimationFrame(()=>{target.scrollTop=target.scrollHeight-oldHeight+oldTop})}
      chatHasMoreBefore=Boolean(data.has_more_before);
    }else{
      observeIncomingChatMessages(items.filter(item=>!chatMessageIsRendered(item.id)));
      appendNewChatMessages(items,forceScroll);
    }
    updateChatReadReceipts(data.peer_last_read_message_id,data.peer_last_read_at);
    updateChatHistoryBar();
    if(data.peer)renderChatConversationHeader(data.peer);
    clearChatNetworkStatus();
    return data;
  })();
  chatMessageRequests.set(requestKey,task);
  try{return await task}finally{if(chatMessageRequests.get(requestKey)===task)chatMessageRequests.delete(requestKey)}
}
async function loadOlderChatMessages(){if(!chatHasMoreBefore||!chatOldestMessageId)return;const button=byId('chatHistoryBar')?.querySelector('button');if(button){button.disabled=true;button.textContent='正在加载…'}try{await loadChatMessages('older')}catch(error){if(button){button.disabled=false;button.textContent='加载失败，点击重试'}}}
async function loadChat(force=false){try{await loadAuthState();await loadChatUsers();if(chatPeerId&&chatUsers.some(item=>item.id===chatPeerId))await loadChatMessages(force?'initial':'newer');else if(chatUsers.length)await selectChatPeer(chatUsers[0].id);startChatPolling()}catch(error){handleChatBackgroundError(error);byId('chatPeerList').innerHTML=`<p class="chat-empty">${isChatNetworkError(error)?'网络刚刚闪断，正在自动恢复…':escapeChatHtml(error.message||'联系人读取失败')}</p>`}}
function startChatPolling(){clearInterval(chatPollTimer);clearInterval(chatMessagePollTimer);chatPollTimer=setInterval(()=>loadChatUsers().catch(handleChatBackgroundError),3000);chatMessagePollTimer=setInterval(()=>{if(byId('chat')?.classList.contains('active')&&chatPeerId)loadChatMessages('newer').catch(handleChatBackgroundError)},1000)}
function syncChatAfterWake(){if(!authState.user_id||document.visibilityState==='hidden')return;loadChatUsers().catch(handleChatBackgroundError);if(byId('chat')?.classList.contains('active')&&chatPeerId)loadChatMessages('newer').catch(handleChatBackgroundError)}
function updateChatComposer(){const input=byId('chatInput'),count=byId('chatCharCount');if(count)count.textContent=`${input?.value.length||0} / 2000`}
function toggleChatEmojiPicker(event){event?.stopPropagation();byId('chatEmojiPicker')?.classList.toggle('hidden')}
function insertChatEmoji(emoji){const input=byId('chatInput');if(!input||input.disabled)return;const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.value=input.value.slice(0,start)+emoji+input.value.slice(end);input.selectionStart=input.selectionEnd=start+emoji.length;updateChatComposer();input.focus();byId('chatEmojiPicker')?.classList.add('hidden')}
function chooseChatImage(){if(chatPeerId)byId('chatImageInput')?.click()}
function setChatImage(file){if(!file)return;if(!['image/jpeg','image/png','image/gif','image/webp'].includes(file.type)){alert('只支持 JPG、PNG、GIF 或 WEBP 图片。');return}if(file.size>5*1024*1024){alert('单张图片不能超过 5MB。');return}clearChatImage();chatPendingImage=file;chatPendingImageUrl=URL.createObjectURL(file);byId('chatImagePreviewThumb').src=chatPendingImageUrl;byId('chatImagePreviewName').textContent=`${file.name} · ${chatFileSize(file.size)}`;byId('chatImagePreview').classList.remove('hidden')}
function clearChatImage(){if(chatPendingImageUrl)URL.revokeObjectURL(chatPendingImageUrl);chatPendingImage=null;chatPendingImageUrl='';const input=byId('chatImageInput'),preview=byId('chatImagePreview'),thumb=byId('chatImagePreviewThumb');if(input)input.value='';if(preview)preview.classList.add('hidden');if(thumb)thumb.removeAttribute('src')}
async function sendChatMessage(event){event.preventDefault();if(chatSendInFlight)return;const input=byId('chatInput'),message=input.value.trim(),status=byId('chatSendStatus');if(!chatPeerId||(!message&&!chatPendingImage))return;const recipientId=Number(chatPeerId),button=event.currentTarget.querySelector('button[type="submit"]');chatSendInFlight=true;button.disabled=true;if(status){delete status.dataset.networkStatus;status.textContent=chatPendingImage?'正在上传并发送…':'正在发送…'}try{let options;if(chatPendingImage){const form=new FormData();form.append('recipient_id',String(recipientId));form.append('body',message);form.append('image',chatPendingImage,chatPendingImage.name);options={method:'POST',headers:{'X-CSRF-Token':authState.csrf_token},body:form}}else{options={method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({recipient_id:recipientId,body:message})}}const response=await fetch('/api/chat/messages',options),data=await response.json();if(!response.ok)throw new Error(data.error||'发送失败');input.value='';clearChatImage();updateChatComposer();if(Number(chatPeerId)===recipientId&&data.item)appendNewChatMessages([data.item],true);if(status)status.textContent='已发送';loadChatUsers().catch(handleChatBackgroundError)}catch(error){if(isChatNetworkError(error)){if(status){status.dataset.networkStatus='1';status.textContent='连接刚刚中断，正在核对发送结果…'}setTimeout(()=>{loadChatMessages('newer',true).then(()=>{if(status){status.dataset.networkStatus='1';status.textContent='连接已恢复，请确认消息是否已经显示'}}).catch(handleChatBackgroundError);loadChatUsers().catch(handleChatBackgroundError)},600)}else if(status){status.textContent=`发送失败：${error.message||'请稍后重试'}`}}finally{chatSendInFlight=false;button.disabled=false;input.focus();setTimeout(()=>{if(status&&status.textContent==='已发送')status.textContent='内容仅在登录账号间可见 · 最多保留 30 天'},1800)}}
async function clearMyChatHistory(){if(!chatPeerId||!confirm('只清空你自己看到的历史记录？对方的聊天记录不会受到影响。'))return;const response=await fetch(`/api/chat/conversations/${chatPeerId}/clear`,{method:'POST',headers:{'X-CSRF-Token':authState.csrf_token}}),data=await response.json();if(!response.ok){alert(data.error||'清空失败');return}chatLastMessageId=0;chatOldestMessageId=0;chatHasMoreBefore=false;updateChatHistoryBar();byId('chatMessages').innerHTML='<p class="chat-empty">你的历史记录已经清空，对方记录保持不变。</p>';await loadChatUsers()}
