function addBasisOpeningCells(targetId,prefix,openings){const target=byId(targetId);if(!target)return;target.querySelectorAll(`tr.${prefix}-group-start`).forEach(row=>{if(row.querySelector('.basis-opening-cell'))return;const symbol=row.querySelector('td.symbol .symbol-detail-trigger')?.textContent||row.querySelector('td.symbol>div:last-of-type>span')?.textContent;if(!symbol)return;const span=Number(row.querySelector('td.symbol')?.rowSpan)||1;const key=`${prefix}:${symbol}`;row.insertAdjacentHTML('beforeend',`<td class="basis-opening-cell" rowspan="${span}">${basisOpeningMarkup(openings[symbol],key)}</td>`)})}
function addBasisOpeningHeaders(){const dualTable=byId('dual-futures')?.querySelector('table'),dualHeader=dualTable?.querySelector('thead tr');if(dualHeader&&!dualTable.classList.contains('dual-redesign-table')&&!dualHeader.querySelector('.basis-opening-column'))dualHeader.insertAdjacentHTML('beforeend','<th class="basis-opening-column">基差打开</th>')}
function applyGroupFrameClasses(targetId,prefix){const target=byId(targetId);if(!target)return;let rowsRemaining=0;[...target.querySelectorAll('tr')].forEach(row=>{row.classList.remove(`${prefix}-group-start`,`${prefix}-group-body`,`${prefix}-group-end`);const symbolCell=row.querySelector('td.symbol[rowspan]');if(symbolCell){rowsRemaining=Number(symbolCell.rowSpan)||1;row.classList.add(`${prefix}-group-start`);if(rowsRemaining===1)row.classList.add(`${prefix}-group-end`)}else if(rowsRemaining===1){row.classList.add(`${prefix}-group-end`)}else if(rowsRemaining>1){row.classList.add(`${prefix}-group-body`)}rowsRemaining=Math.max(0,rowsRemaining-1)});if(prefix!=='spot'&&!byId('dual-futures')?.querySelector('.dual-redesign-table'))addBasisOpeningCells(targetId,prefix,dualBasisOpenings);const dividerClass=`${prefix}-group-divider`,columns=prefix==='spot'?11:5;if(!target.querySelector(`.${dividerClass}`))target.querySelectorAll(`tr.${prefix}-group-end`).forEach(row=>row.insertAdjacentHTML('afterend',`<tr class="${dividerClass}" aria-hidden="true"><td colspan="${columns}"></td></tr>`))}
