function thoughtPrice(value){const n=Number(value);return Number.isFinite(n)?n.toFixed(8):'暂无'}
function thoughtPercent(value){return value===null||value===undefined?'暂无':percent(value)}
function thoughtLarge(value){const n=Number(value);if(!Number.isFinite(n))return '暂无';if(Math.abs(n)>=1e9)return `$${(n/1e9).toFixed(2)}B`;if(Math.abs(n)>=1e6)return `$${(n/1e6).toFixed(2)}M`;return `$${n.toFixed(2)}`}
function thoughtList(items){return `<ul>${items.map(item=>`<li>${item}</li>`).join('')}</ul>`}
function thoughtShort(text,max=170){const value=String(text||'暂无');return value.length>max?value.slice(0,max)+'…':value}
function thoughtMistakePanel(title,items,type){const list=(items&&items.length?items:['暂无需要单独标记的偏差。']);return `<section class="thought-mistake ${type}"><h4>${title}</h4>${thoughtList(list)}</section>`}
function thoughtValidation(item){const validation=item.validation||{};return ['30m','1h','2h'].map(key=>{const row=validation[key]||{};return `<span>${key.toUpperCase()} <b class="${changeClass(row.price_change)}">价 ${thoughtPercent(row.price_change)}</b><i>持仓 ${thoughtPercent(row.oi_change)} · 人数比 ${thoughtPercent(row.ratio_change)} · CVD ${thoughtLarge(row.cvd)} · 量 ${thoughtLarge(row.volume)}</i></span>`}).join('')}
function thoughtHorizonHit(value){return {take_profit:'先到虚拟止盈',hard_stop:'先到结构硬止损',ambiguous_same_candle:'同根K线先后不明'}[value]||'验证中'}
function thoughtHorizonEvent(value){return {take_profit:'触及虚拟止盈',soft_stop:'进入软警戒区',hard_stop:'触及结构硬止损',ambiguous_same_candle:'止盈/止损同根覆盖',near_target_then_reversal:'接近目标后反转',interim_review:'阶段复核',final_review:'到期复盘'}[value]||value}
function thoughtHorizonHtml(item){const rows=item.horizon_validations||[];if(!rows.length)return'';return `<section class="thought-horizon-panel"><div class="thought-horizon-title"><div><h4>多周期趋势验证</h4><p>同一时点分别立案；触发止盈/止损后仍观察到周期结束，用来识别扫损后反转、未到目标便反转和来回震荡。</p></div><span>虚拟验证 · 非实盘指令</span></div><div class="thought-horizon-grid">${rows.map(row=>{const direction=row.direction==='long'?'偏多':'偏空',directionClass=row.direction==='long'?'long':'short',review=row.final_review||row.interim_review||'',events=(row.events||[]).slice(0,5);return `<article class="thought-horizon-card ${directionClass}"><header><span>${row.label} · ${row.window}</span><b>${direction} ${Number(row.confidence||0).toFixed(0)}%</b></header><div class="thought-horizon-prices"><span>立案价<b>${thoughtPrice(row.anchor_price)}</b></span><span>现价<b>${thoughtPrice(row.latest_price)}</b></span><span>止盈<b class="positive">${thoughtPrice(row.take_profit_price)}</b></span><span>软警戒<b>${thoughtPrice(row.soft_stop_price)}</b></span><span>硬止损<b class="negative">${thoughtPrice(row.hard_stop_price)}</b></span></div><p class="thought-horizon-thesis">${row.hypothesis}</p><p class="thought-horizon-invalid"><b>失效确认：</b>${row.invalidation_rule}</p><div class="thought-horizon-path"><span>${thoughtHorizonHit(row.first_hit)}${row.first_hit_at?` · ${row.first_hit_at}`:''}</span><i>最大有利 ${Number(row.max_favorable_pct||0).toFixed(2)}% · 最大不利 ${Number(row.max_adverse_pct||0).toFixed(2)}%</i><em>${row.status==='active'?`最晚复盘 ${row.expires_at}`:'本周期已完成'}</em></div>${review?`<p class="thought-horizon-review">${review}</p>`:''}${events.length?`<div class="thought-horizon-events">${events.map(event=>`<small><b>${event.at}</b>${thoughtHorizonEvent(event.type)}${event.price?` · ${thoughtPrice(event.price)}`:''}</small>`).join('')}</div>`:''}</article>`}).join('')}</div></section>`}
function toggleThoughtShot(id){byId(id)?.classList.toggle('hidden')}
const expandedThoughts=new Set();
function toggleThoughtRecord(id,button){const detail=byId(`thought-detail-${id}`);if(!detail)return;detail.classList.toggle('hidden');const opened=!detail.classList.contains('hidden');opened?expandedThoughts.add(id):expandedThoughts.delete(id);const label=button?.querySelector('em');if(label)label.textContent=opened?'收起':'展开'}
function thoughtProfitLabel(item){const rate=item.thesis_win_rate?.rate??0;if(item.trade_side==='观察')return `<span>思路胜率 ${rate}%</span>`;if(item.trade_status==='已平仓')return `<span class="${changeClass(item.realized_profit_pct)}">已实现 ${thoughtPercent(item.realized_profit_pct)}</span>`;if(item.profit_pct!==null&&item.profit_pct!==undefined)return `<span class="${changeClass(item.profit_pct)}">浮盈 ${thoughtPercent(item.profit_pct)}</span>`;return `<span>思路胜率 ${rate}%</span>`}
function thoughtSideClass(item){return item.trade_side==='做多'?'long':(item.trade_side==='做空'?'short':'watch')}
function thoughtSideBadge(item){return `<span class="thought-side-badge ${thoughtSideClass(item)}">${item.trade_side||'观察'}</span>`}
function thoughtSummaryLine(item){const side=item.trade_side||'观察',status=item.trade_status||'盯盘',entry=item.entry!==null&&item.entry!==undefined?` · 入场 ${thoughtPrice(item.entry)}`:'';if(item.trade_status==='已平仓')return `${side} · ${status}${entry} · 止盈 ${thoughtPrice(item.exit)} · 当前 ${thoughtPrice(item.last)}`;return `${side} · ${status}${entry} · 当前 ${thoughtPrice(item.last)}`}
function thoughtCard(item){const id=item.symbol.replace(/[^A-Z0-9]/g,''),shotId=`thought-shot-${id}`,expanded=expandedThoughts.has(id),stage=item.stage_label?`<span class="thought-stage stage-${item.stage_label.includes('第0')?0:item.stage_label.includes('第1')?1:item.stage_label.includes('第2')?2:item.stage_label.includes('第3')?3:4}">${item.stage_label}</span>`:'',entryDetail=item.entry!==null&&item.entry!==undefined?` · 入场 ${thoughtPrice(item.entry)}`:'';return `<article class="thought-card compact ${thoughtSideClass(item)}"><button type="button" class="thought-summary" onclick="toggleThoughtRecord('${id}',this)"><span><b>${item.symbol} ${thoughtSideBadge(item)} ${stage}</b><i>${thoughtSummaryLine(item)}</i></span>${thoughtProfitLabel(item)}<strong>胜率 ${item.thesis_win_rate?.rate??0}%</strong><em>${expanded?'收起':'展开'}</em></button><div id="thought-detail-${id}" class="thought-detail ${expanded?'':'hidden'}"><div class="thought-card-head"><div><p class="eyebrow">ACTIVE REVIEW</p><h3>${item.symbol} 思路复盘 ${thoughtSideBadge(item)} ${stage}</h3><small>${item.trade_status||'盯盘'}${entryDetail} · 当前 ${thoughtPrice(item.last)} · 胜率 ${item.thesis_win_rate?.rate??0}%</small></div><div class="thought-actions">${item.screenshot_url?`<button type="button" class="shot-toggle" onclick="event.stopPropagation();toggleThoughtShot('${shotId}')">截图</button>`:''}<a class="kline-link" target="_blank" rel="noopener noreferrer" href="${coinglassKlineUrl(item.symbol)}" onclick="event.stopPropagation()">K线</a></div></div>${item.screenshot_url?`<div id="${shotId}" class="thought-shot hidden"><img src="${item.screenshot_url}" alt="${item.symbol} CoinGlass 数据截图"></div>`:''}<section class="thought-core"><h4>核心判断</h4><p>${thoughtShort(item.thought_summary||item.my_thesis,220)}</p></section>${thoughtHorizonHtml(item)}<div class="thought-two-col mistake-grid">${thoughtMistakePanel('你的偏差 / 需要修正',item.user_mistakes,'user')}${thoughtMistakePanel('我的失误 / 规则修正',item.assistant_mistakes,'assistant')}</div><section><h4>当前验证</h4><p>${thoughtShort(item.validation_view,220)}</p><div class="thought-validation">${thoughtValidation(item)}</div></section><div class="thought-two-col"><section><h4>止盈计划</h4>${thoughtList((item.take_profit||[]).slice(0,3))}</section><section><h4>止损计划</h4>${thoughtList((item.stop_loss||[]).slice(0,3))}</section></div><section><h4>复盘记录</h4>${thoughtList((item.review_notes||[]).slice(0,4))}</section><p class="thought-source">${item.thesis_win_rate?.note||''} · 数据来源：${item.source==='live'?'Binance 公开实时接口':'本地快照降级'}。</p></div></article>`}
function thoughtWatchDuration(seconds){const total=Math.max(0,Number(seconds)||0),days=Math.floor(total/86400),hours=Math.floor(total%86400/3600),minutes=Math.floor(total%3600/60);return days?`${days}天${hours}小时`:(hours?`${hours}小时${minutes}分`:`${minutes}分钟`)}
function thoughtWatchValue(value,suffix=''){const n=Number(value);return Number.isFinite(n)?`${n>=0?'+':''}${n.toFixed(2)}${suffix}`:'—'}
function thoughtWatchCard(item){const trend=Number(item.change_pct),trendClass=Number.isFinite(trend)?(trend>0?'positive':trend<0?'negative':'muted'):'muted',base=item.symbol.split('/')[0],control=authState.is_admin?`<button class="${item.active?'stop':'resume'}" onclick="toggleThoughtWatch('${base}','${item.active?'stop':'resume'}',this)">${item.active?'停止盯盘':'重新盯盘'}</button>`:'';return `<article class="thought-watch-card ${item.active?'active':'stopped'}"><div class="thought-watch-head"><span class="watch-state-dot"></span><div><b>${item.symbol}</b><small>${item.active?'正在盯盘':'已停止盯盘'} · ${item.note||''}</small></div><a href="${coinglassKlineUrl(item.symbol)}" target="_blank" rel="noopener noreferrer">K线</a></div><div class="thought-watch-time"><span>开始时间<b>${item.started_at||'—'}</b></span><span>${item.active?'已盯盘':'停止时间'}<b>${item.active?thoughtWatchDuration(item.duration_seconds):(item.stopped_at||'—')}</b></span></div><div class="thought-watch-prices"><span>开始价格<b>${thoughtPrice(item.start_price)}</b></span><span>${item.active?'当前价格':'停止价格'}<b>${thoughtPrice(item.active?item.current_price:item.stop_price)}</b></span><span>后续走势<b class="${trendClass}">${thoughtWatchValue(item.change_pct,'%')}</b></span></div><div class="thought-watch-range"><span>记录最高 <b class="positive">${thoughtPrice(item.high_price)} · ${thoughtWatchValue(item.high_change_pct,'%')}</b></span><span>记录最低 <b class="negative">${thoughtPrice(item.low_price)} · ${thoughtWatchValue(item.low_change_pct,'%')}</b></span></div><div class="thought-watch-foot"><small>${item.last_push_at?`最近推送 ${item.last_push_at}`:'尚无正式推送'}</small>${control}</div></article>`}
function thoughtWatchAddPanel(){return `<form class="thought-watch-add" onsubmit="addThoughtWatch(event)"><div><b>加入新的盯盘币种</b><small>加入后每 5 分钟自动读取行情、验证结构；出现新的确定性判断时才推送。</small></div><div class="thought-watch-add-actions"><div class="thought-watch-add-search"><input id="thoughtWatchAddInput" type="search" autocomplete="off" placeholder="输入币种，例如 BTC" oninput="loadThoughtWatchAddSuggestions(this.value)"><div id="thoughtWatchAddSuggestions" class="thought-watch-add-suggestions hidden"></div></div><button type="submit">＋ 开始盯盘</button></div></form>`}
async function loadThoughtWatchAddSuggestions(query){const panel=byId('thoughtWatchAddSuggestions'),normalized=query.trim();if(!panel)return;if(!normalized){panel.innerHTML='';panel.classList.add('hidden');return}const requestId=++thoughtWatchSuggestionRequest;try{const response=await fetch('/api/symbol-suggestions?q='+encodeURIComponent(normalized));const data=await response.json();if(requestId!==thoughtWatchSuggestionRequest)return;const items=(data.items||[]).slice(0,8);panel.innerHTML=items.length?items.map(item=>`<button type="button" onclick="selectThoughtWatchSuggestion('${item.symbol}')"><b>${item.symbol.split('/')[0]}</b><small>${item.symbol}${item.live?'':' · 暂无当前行情'}</small></button>`).join(''):'<p>没有匹配的 Binance 合约币种</p>';panel.classList.remove('hidden')}catch(error){panel.innerHTML='';panel.classList.add('hidden')}}
function selectThoughtWatchSuggestion(symbol){const input=byId('thoughtWatchAddInput'),panel=byId('thoughtWatchAddSuggestions');if(input)input.value=symbol;if(panel)panel.classList.add('hidden')}
async function addThoughtWatch(event){event.preventDefault();const form=event.currentTarget,input=byId('thoughtWatchAddInput'),button=form?.querySelector('button[type="submit"]'),symbol=input?.value.trim();if(!symbol){input?.focus();return}if(button){button.disabled=true;button.textContent='正在加入…'}try{const response=await fetch('/api/thought-watchlist',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({symbol})});const data=await response.json();if(!response.ok)throw new Error(data.error||'加入盯盘失败');await loadThoughtAnalysis()}catch(error){alert(error.message||'加入盯盘失败');if(button){button.disabled=false;button.textContent='＋ 开始盯盘'}}}
function thoughtWatchManager(data){const items=data?.items||[],active=items.filter(item=>item.active),stopped=items.filter(item=>!item.active);return `<section class="thought-watch-manager"><div class="thought-watch-title"><div><p class="eyebrow">WATCH MANAGEMENT</p><h3>盯盘管理 <em>${active.length} 个运行中</em></h3><small>${authState.is_admin?'可以直接管理盯盘币种；停止后保留历史走势和思路记录。':'查看账号只能读取盯盘状态，不能修改。'}</small></div><span>最近更新 ${data?.updated_at||'—'}</span></div>${authState.is_admin?thoughtWatchAddPanel():''}<div class="thought-watch-grid">${active.map(thoughtWatchCard).join('')||'<p class="empty-alert">当前没有运行中的盯盘币种。</p>'}</div>${stopped.length?`<details class="thought-watch-stopped"><summary>已停止盯盘 · ${stopped.length} 个</summary><div class="thought-watch-grid">${stopped.map(thoughtWatchCard).join('')}</div></details>`:''}</section>`}
async function toggleThoughtWatch(symbol,action,button){if(button)button.disabled=true;try{const response=await fetch(`/api/thought-watchlist/${encodeURIComponent(symbol)}/state`,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':authState.csrf_token},body:JSON.stringify({action})});const data=await response.json();if(!response.ok)throw new Error(data.error||'操作失败');await loadThoughtAnalysis()}catch(error){alert(error.message||'盯盘状态修改失败');if(button)button.disabled=false}}
async function loadThoughtAnalysis(){const target=byId('thoughtAnalysis');if(!target)return;if(!target.dataset.loaded&&!target.children.length)target.innerHTML='<p class="loading">正在读取思路分析…</p>';target.classList.add('soft-loading');try{const [thoughtResponse,watchResponse]=await Promise.all([fetch('/api/daily-report/thoughts'),fetch('/api/thought-watchlist')]);const data=await thoughtResponse.json(),watchData=await watchResponse.json();target.dataset.loaded='1';const records=data.items?.length?data.items.map(thoughtCard).join(''):'<p class="empty-alert">暂无思路分析记录。</p>';target.innerHTML=thoughtWatchManager(watchData)+`<div class="thought-record-list"><div class="thought-record-heading"><p class="eyebrow">THOUGHT REVIEW</p><h3>思路记录</h3></div>${records}</div>`}catch(error){if(!target.dataset.loaded)target.innerHTML='<p class="empty-alert">思路分析暂时无法读取。</p>'}finally{target.classList.remove('soft-loading')}}
function fundingTrendRow(item){return `<article class="funding-trend-card ${item.level==='重点机会'?'hot':item.level==='重点盯盘'?'watch':'observe'}"><div class="funding-trend-head"><div><b><button class="symbol-detail-trigger" onclick="openSymbolDetail('${item.symbol}')">${item.symbol}</button></b><span>${item.long_exchange} 现货 → Binance 合约 <em class="interval-badge ${intervalClass(item.funding_interval)}">${item.funding_interval||8}H</em></span></div><strong>${item.level}</strong><i>${Number(item.score||0).toFixed(1)}</i></div><div class="funding-trend-grid"><span>24H涨幅 <b class="${changeClass(item.change_24h)}">${displayChange(item.change_24h)}</b></span><span>3D涨幅 <b class="${changeClass(item.change_3d)}">${displayChange(item.change_3d)}</b></span><span>当前资费 <b class="${changeClass(item.funding_current)}">${percent(item.funding_current)}</b></span><span>上期资费 <b class="${changeClass(item.funding_previous)}">${percent(item.funding_previous)}</b></span><span>24H资费 <b class="${changeClass(item.funding_24h)}">${percent(item.funding_24h)}</b></span><span>3D资费 <b class="${changeClass(item.funding_3d)}">${percent(item.funding_3d)}</b></span><span>基差 <b class="${changeClass(item.basis)}">${percent(item.basis)}</b></span><span>开差 <b class="${changeClass(item.open_spread)}">${percent(item.open_spread)}</b></span><span>12H持仓变化 <b class="${changeClass(item.oi_change_12h)}">${displayChange(item.oi_change_12h)}</b></span><span>12H量能变化 <b class="${changeClass(item.volume_change_12h)}">${displayChange(item.volume_change_12h)}</b></span><span>合约持仓 <b>${liquidityAmount(item.futures_open_interest)}</b></span><span>合约交易量 <b>${liquidityAmount(item.futures_volume)}</b></span></div></article>`}
async function loadFundingTrend(){const target=byId('fundingTrendList');if(!target)return;const hasOld=target.dataset.loaded==='1';if(!hasOld)target.innerHTML='<p class="loading">正在扫描主升正资费机会…</p>';else target.classList.add('soft-loading');try{const data=await (await fetch('/api/arbitrage-thinking/funding-trend')).json();target.dataset.loaded='1';target.innerHTML=data.items?.length?`<p class="funding-trend-updated">最近更新：${data.updated_at||'—'} · 按机会评分排序，持仓/交易量只看增长趋势不做硬过滤。</p>${data.items.map(fundingTrendRow).join('')}`:'<p class="empty-alert">当前没有进入主升正资费观察的币种。</p>'}catch(error){if(!hasOld)target.innerHTML='<p class="empty-alert">主升正资费榜暂时无法读取。</p>'}finally{target.classList.remove('soft-loading')}}
function tradePrice(value){const n=Number(value);return Number.isFinite(n)?n.toFixed(n>=1?4:6):'--'}
function tradeStatusLabel(status){return status==='planned'?'等待触发':status==='open'?'验证中':status==='cancelled'?'已停止':'已结算'}
function tradeDirectionLabel(direction){return direction==='short'?'做空':'做多'}
function tradeExitReasonLabel(reason){return ({stop:'止损',take_profit:'止盈',breakeven_after_tp1:'止盈后保本退出',momentum_failed:'短线动能失效',time_exit:'短线时间退出',manual_stop:'手动停止',signal_reversed:'新结构反向',entry_drifted:'价格背离入场位',entry_out_of_range:'入场位脱离当前结构',structure_repriced:'结构重新定价',plan_expired:'结构已过期'})[reason]||reason||'--'}
function tradePnlClass(value){return Number(value)>=0?'positive':'negative'}
function tradeChart(plan){
  const candles=plan.candles||[];
  if(candles.length<2)return '<div class="trade-chart-empty">暂无足够 K 线缓存</div>';
  const entry=Number(plan.entry_price),stop=Number(plan.stop_price),tp1=Number(plan.take_profit_1),tp2=Number(plan.take_profit_2),current=Number(plan.current_price);
  const levels=[entry,stop,tp1,tp2,current],prices=candles.flatMap(c=>[c.high,c.low,c.open,c.close]).concat(levels).map(Number).filter(Number.isFinite);
  const min=Math.min(...prices)*.996,max=Math.max(...prices)*1.004;
  const candleStep=12,candleBody=7,w=Math.max(1280,candles.length*candleStep+170),h=460,m={l:18,r:94,t:28,b:34},priceH=310,volumeTop=356,volumeH=66,iw=w-m.l-m.r;
  const x=i=>m.l+i*candleStep+8,y=p=>m.t+(max-p)*priceH/(max-min),volMax=Math.max(...candles.map(c=>Number(c.volume)||0),1);
  const gridPrices=Array.from({length:6},(_,i)=>min+(max-min)*i/5).reverse();
  const grid=gridPrices.map(p=>`<line x1="${m.l}" x2="${w-m.r}" y1="${y(p)}" y2="${y(p)}" class="tv-grid"/><text x="${w-m.r+8}" y="${y(p)+4}" class="tv-axis">${tradePrice(p)}</text>`).join('')+
    Array.from({length:Math.floor(candles.length/24)+1},(_,i)=>i*24).filter(i=>i<candles.length).map(i=>`<line x1="${x(i)}" x2="${x(i)}" y1="${m.t}" y2="${volumeTop+volumeH}" class="tv-grid vertical"/><text x="${x(i)-18}" y="${h-12}" class="tv-time">${candles[i].time}</text>`).join('');
  const bodies=candles.map((c,i)=>{const up=Number(c.close)>=Number(c.open),cx=x(i),top=y(Math.max(c.open,c.close)),height=Math.max(1.5,Math.abs(y(c.open)-y(c.close))),vy=volumeTop+volumeH-(Number(c.volume)||0)/volMax*volumeH;return `<line x1="${cx}" x2="${cx}" y1="${y(c.high)}" y2="${y(c.low)}" class="${up?'tv-up':'tv-down'}"/><rect x="${cx-candleBody/2}" y="${top}" width="${candleBody}" height="${height}" rx="1" class="${up?'tv-up':'tv-down'}"/><rect x="${cx-candleBody/2}" y="${vy}" width="${candleBody}" height="${volumeTop+volumeH-vy}" class="${up?'tv-vol-up':'tv-vol-down'}"/>`}).join('');
  const isShort=plan.direction==='short',touch=(price,from=0,mode='any')=>{const p=Number(price);for(let i=Math.max(0,from);i<candles.length;i++){const c=candles[i];if(mode==='long-up'&&Number(c.high)>=p)return i;if(mode==='long-down'&&Number(c.low)<=p)return i;if(mode==='short-down'&&Number(c.low)<=p)return i;if(mode==='short-up'&&Number(c.high)>=p)return i;if(mode==='any'&&Number(c.low)<=p&&Number(c.high)>=p)return i}return -1};
  const entryIdx=touch(entry,0,isShort?'short-down':'long-up'),start=entryIdx>=0?entryIdx:0,tp1Idx=touch(tp1,start,isShort?'short-down':'long-up'),tp2Idx=touch(tp2,start,isShort?'short-down':'long-up'),stopIdx=touch(stop,start,isShort?'short-up':'long-down');
  const priceLine=(price,cls,label)=>Number.isFinite(Number(price))?`<line x1="${m.l}" x2="${w-m.r}" y1="${y(price)}" y2="${y(price)}" class="${cls}"/><text x="${w-m.r+8}" y="${y(price)+4}" class="tv-level-label">${label} ${tradePrice(price)}</text>`:'';
  const marker=(idx,price,cls,label)=>idx>=0?`<g class="trade-point ${cls}" transform="translate(${x(idx)},${y(price)})"><path d="M0,-10 L9,0 L0,10 L-9,0 Z"/><text x="12" y="-9">${label}</text></g>`:'';
  const currentLine=Number.isFinite(current)?`<line x1="${m.l}" x2="${w-m.r}" y1="${y(current)}" y2="${y(current)}" class="tv-current-line"/><rect x="${w-m.r+4}" y="${y(current)-13}" width="78" height="24" rx="3" class="${current>=Number(candles[candles.length-1].open)?'tv-price-tag up':'tv-price-tag down'}"/><text x="${w-m.r+9}" y="${y(current)+4}" class="tv-price-text">${tradePrice(current)}</text>`:'';
  const replayEvents=(plan.events||[]).map(event=>({idx:Number(event.idx),price:Number(event.price),label:event.label||({entry:isShort?'开空':'买入',tp1:'止盈1',tp2:'止盈2',stop:'止损'}[event.type]||event.type),cls:event.type==='entry'?'buy':event.type==='stop'?'stop':'sell',type:event.type})).filter(item=>Number.isFinite(item.idx)&&item.idx>=0);
  const plannedIdx=Math.max(0,candles.length-1);
  const plannedEvents=plan.status==='planned'
    ? [{idx:plannedIdx,price:entry,label:isShort?'计划开空':'计划买入',cls:'buy',type:'entry'},{idx:plannedIdx,price:tp1,label:'计划止盈1',cls:'sell',type:'tp1'},{idx:plannedIdx,price:tp2,label:'计划止盈2',cls:'sell',type:'tp2'},{idx:plannedIdx,price:stop,label:'计划止损',cls:'stop',type:'stop'}]
    : [];
  const openPlanEvents=(plan.status==='open'&&replayEvents.length)
    ? [{idx:plannedIdx,price:tp1,label:'计划止盈1',cls:'sell',type:'tp1-plan'},{idx:plannedIdx,price:tp2,label:'计划止盈2',cls:'sell',type:'tp2-plan'},{idx:plannedIdx,price:stop,label:'计划止损',cls:'stop',type:'stop-plan'}]
    : [];
  const timelineEvents=replayEvents.length?[...replayEvents,...openPlanEvents]:(plannedEvents.length?plannedEvents:[{idx:entryIdx,price:entry,label:isShort?'开空':'买入',cls:'buy',type:'entry'},{idx:tp1Idx,price:tp1,label:'止盈1',cls:'sell',type:'tp1'},{idx:tp2Idx,price:tp2,label:'止盈2',cls:'sell',type:'tp2'},{idx:stopIdx,price:stop,label:'止损',cls:'stop',type:'stop'}].filter(item=>item.idx>=0));
  const closedWithReplay=replayEvents.length&&plan.status==='closed',eventTypes=new Set(timelineEvents.map(item=>item.type));
  const levelLines=closedWithReplay
    ? `${eventTypes.has('entry')?priceLine(entry,'entry-line',isShort?'开空':'入场'):''}${eventTypes.has('tp1')?priceLine(tp1,'tp-line','止盈1'):''}${eventTypes.has('tp2')?priceLine(tp2,'tp-line','止盈2'):''}${eventTypes.has('stop')?priceLine(stop,'stop-line','止损'):''}`
    : `${priceLine(entry,'entry-line','入场')}${priceLine(tp1,'tp-line','止盈1')}${priceLine(tp2,'tp-line','止盈2')}${priceLine(stop,'stop-line','止损')}`;
  const eventMarkers=timelineEvents.map(item=>marker(item.idx,item.price,item.cls,item.label)).join('');
  const timelineStack={};
  const timelineMarkers=timelineEvents.map(item=>{const stack=timelineStack[item.idx]||0;timelineStack[item.idx]=stack+1;return `<button type="button" class="trade-scroll-marker ${item.cls}" style="left:${(x(item.idx)/w*100).toFixed(3)}%;top:${stack*15}px" data-ratio="${(x(item.idx)/w).toFixed(6)}" title="${item.label} · 第 ${item.idx+1} 根K线"><i></i><span>${item.label}</span></button>`}).join('');
  const hoverTimes=encodeURIComponent(JSON.stringify(candles.map(c=>c.time)));
  return `<div class="trade-chart-shell"><div class="trade-chart-topbar"><span>${plan.symbol} · 5m · Binance</span><div class="trade-chart-legend"><b class="entry">入场线</b><b class="tp">止盈线</b><b class="stop">止损线</b><b class="current">现价线</b></div></div><div class="trade-chart-scroll tv-scroll" data-chart-width="${w}" data-candle-step="${candleStep}" data-candle-left="${m.l+8}" data-candle-times="${hoverTimes}" aria-label="${plan.symbol} K线可横向滑动"><div class="trade-chart-track" style="width:${w}px"><svg class="trade-chart tv-chart" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${plan.symbol} 趋势验证K线图"><rect x="0" y="0" width="${w}" height="${h}" class="tv-bg"/><rect x="${m.l}" y="${m.t}" width="${iw}" height="${priceH}" class="tv-panel"/><rect x="${m.l}" y="${volumeTop}" width="${iw}" height="${volumeH}" class="tv-volume-panel"/>${grid}<text x="${m.l}" y="${volumeTop-9}" class="tv-volume-title">Volume</text>${bodies}${levelLines}${currentLine}${eventMarkers}</svg></div><div class="trade-crosshair-line hidden"></div><div class="trade-crosshair-time hidden">--</div></div><div class="trade-chart-scroll-controls"><button type="button" class="trade-chart-shift" data-shift="-1">← 看历史</button><div class="trade-chart-timeline"><div class="trade-scroll-markers">${timelineMarkers}</div><div class="trade-chart-native-scroll" aria-label="拖动查看前后K线"><div style="width:${w}px;height:1px"></div></div></div><button type="button" class="trade-chart-shift" data-shift="1">最新 →</button></div><small class="trade-scroll-hint">默认停在最新K线，向左拖动或点“看历史”查看前面的买入卖出点；也可以直接点击时间轴上的剧情点。</small><div class="trade-line-notes"><span><b>绿色实线</b>入场价格，验证计划触发的位置。</span><span><b>蓝色虚线</b>止盈目标，卖出/平仓观察位。</span><span><b>红色虚线</b>止损位置，走势失效保护位。</span><span><b>青色虚线</b>当前价格。</span></div></div>`;
}
const expandedTradePlans=new Set();
function tradePlanDetailHtml(plan){return `<div class="trade-plan-detail-inner">${tradeChart(plan)}<p class="trade-thesis">${plan.thesis||''}</p><div class="trade-plan-foot"><span>计划：${plan.created_at||'--'}</span><span>开仓：${plan.opened_at||'未触发'}</span><span>结束：${plan.closed_at||'--'}</span><span>原因：${tradeExitReasonLabel(plan.exit_reason)} ${plan.exit_price?tradePrice(plan.exit_price):''}</span></div></div>`}
function tradePlanCard(plan){const pnl=Number(plan.pnl||0),key=plan.id||plan.symbol,expanded=expandedTradePlans.has(String(key)),pnlLabel=plan.status==='planned'?'计划盈亏':plan.status==='cancelled'?'停止盈亏':'当前盈亏',horizon=plan.horizon==='short'?'短线':plan.horizon==='medium_long'?'中长线':'旧规则';return `<article class="trade-plan-card ${plan.direction} ${plan.status}" data-plan-key="${key}"><div class="trade-plan-head"><div><p class="eyebrow">SINGLE TRADE VALIDATION</p><h3>${plan.symbol} <span class="${plan.direction}">${tradeDirectionLabel(plan.direction)}</span></h3><small>${tradeStatusLabel(plan.status)} · ${horizon}${plan.max_hold_minutes?`最多${plan.max_hold_minutes}分钟`:''} · 100U · ${plan.leverage}倍 · 暂无手续费</small></div><div class="trade-plan-pnl ${tradePnlClass(pnl)}"><span>${pnlLabel}</span><b>${pnl>=0?'+':''}${pnl.toFixed(2)}U</b></div></div><div class="trade-level-grid"><span>当前价<b>${tradePrice(plan.current_price)}</b></span><span>入场<b>${tradePrice(plan.entry_price)}</b></span><span>止损<b>${tradePrice(plan.stop_price)}</b></span><span>止盈1<b>${tradePrice(plan.take_profit_1)}</b></span><span>止盈2<b>${tradePrice(plan.take_profit_2)}</b></span></div><p class="trade-thesis compact">${plan.thesis||''}</p><button type="button" class="trade-detail-toggle" onclick="toggleTradePlanDetail('${key}',this)">${expanded?'收起K线和详细数据':'展开K线和详细数据'}</button><div class="trade-plan-detail ${expanded?'':'hidden'}">${expanded?'<p class="loading">正在读取K线详情…</p>':''}</div></article>`}
async function toggleTradePlanDetail(key,button){const card=button.closest('.trade-plan-card'),box=card?.querySelector('.trade-plan-detail');if(!card||!box)return;if(expandedTradePlans.has(String(key))){expandedTradePlans.delete(String(key));box.classList.add('hidden');box.innerHTML='';button.textContent='展开K线和详细数据';return}expandedTradePlans.add(String(key));box.classList.remove('hidden');box.innerHTML='<p class="loading">正在读取K线详情…</p>';button.textContent='收起K线和详细数据';try{const plan=await (await fetch(`/api/trade-validation/${encodeURIComponent(key)}/detail`)).json();box.innerHTML=tradePlanDetailHtml(plan);activateTradeChartScrolls(box)}catch(error){box.innerHTML='<p class="empty-alert">K线详情暂时读取失败。</p>'}}
function tradeValidationSummaryHtml(s={}){const rate=s.win_rate===null||s.win_rate===undefined?'--':`${Number(s.win_rate).toFixed(1)}%`,pnl=Number(s.total_pnl||0);return `<article><p>总计划</p><strong>${s.total||0}</strong><small>一笔一笔验证</small></article><article><p>胜率</p><strong>${rate}</strong><small>只统计已结算</small></article><article><p>总盈亏</p><strong class="${tradePnlClass(pnl)}">${pnl>=0?'+':''}${pnl.toFixed(2)}U</strong><small>100U / 1倍 / 无手续费</small></article>`}
const expandedTradeSymbols=new Set();
let currentTradeValidationPlans=[];
function groupedTradePlans(plans){const groups=new Map();plans.forEach(plan=>{if(!groups.has(plan.symbol))groups.set(plan.symbol,[]);groups.get(plan.symbol).push(plan)});return [...groups.values()]}
function tradeSymbolGroupCard(plans){const symbol=plans[0].symbol,closed=plans.filter(plan=>plan.status==='closed'),cancelled=plans.filter(plan=>plan.status==='cancelled'),wins=closed.filter(plan=>Number(plan.pnl||0)>0),pnl=plans.reduce((sum,plan)=>sum+Number(plan.pnl||0),0),active=plans.find(plan=>plan.status==='open')||plans.find(plan=>plan.status==='planned'),latest=active||plans[0],expanded=expandedTradeSymbols.has(symbol),rate=closed.length?wins.length/closed.length*100:null,stoppedText=cancelled.length?` · 已停止 ${cancelled.length} 笔`:'';return `<article class="trade-symbol-group ${active?'active':''}" data-trade-symbol="${symbol}"><div class="trade-symbol-head"><div><p class="eyebrow">SYMBOL VALIDATION HISTORY</p><h3>${symbol}</h3><small>${plans.length} 笔验证 · 已结算 ${closed.length} 笔${stoppedText}${active?` · ${tradeStatusLabel(active.status)} 1笔`:''}</small></div><div class="trade-symbol-metrics"><span>现价<b>${tradePrice(latest.current_price)}</b></span><span>胜率<b>${rate===null?'--':rate.toFixed(1)+'%'}</b></span><span>累计盈亏<b class="${tradePnlClass(pnl)}">${pnl>=0?'+':''}${pnl.toFixed(2)}U</b></span></div></div><button type="button" class="trade-symbol-toggle" onclick="toggleTradeSymbolGroup('${symbol}',this)">${expanded?'收起每笔验证':`查看 ${plans.length} 笔模拟交易`}</button><div class="trade-symbol-trades ${expanded?'':'hidden'}">${expanded?plans.map(tradePlanCard).join(''):''}</div></article>`}
function toggleTradeSymbolGroup(symbol,button){const group=button.closest('.trade-symbol-group'),box=group?.querySelector('.trade-symbol-trades'),plans=currentTradeValidationPlans.filter(plan=>plan.symbol===symbol);if(!group||!box)return;if(expandedTradeSymbols.has(symbol)){expandedTradeSymbols.delete(symbol);box.classList.add('hidden');box.innerHTML='';button.textContent=`查看 ${plans.length} 笔模拟交易`;return}expandedTradeSymbols.add(symbol);box.classList.remove('hidden');box.innerHTML=plans.map(tradePlanCard).join('');button.textContent='收起每笔验证';activateTradeChartScrolls(box)}
function activateTradeChartScrolls(root=document){
  root.querySelectorAll('.trade-chart-scroll').forEach(scroller=>{
    const shell=scroller.closest('.trade-chart-shell'),scrollbar=shell?.querySelector('.trade-chart-native-scroll'),track=scroller.querySelector('.trade-chart-track');
    if(!scrollbar||!track)return;
    const chartWidth=Number(scroller.dataset.chartWidth)||track.offsetWidth||0;
    const maxOffset=Math.max(0,chartWidth-scroller.clientWidth);
    const applyOffset=value=>{const offset=Math.max(0,Math.min(maxOffset,Number(value)||0));if(Math.abs(scrollbar.scrollLeft-offset)>1)scrollbar.scrollLeft=offset;scroller.dataset.offset=String(offset);track.style.transform=`translateX(${-offset}px)`};
    if(!scroller.dataset.chartReady){
      scroller.dataset.chartReady='1';
      applyOffset(maxOffset);
    }else{
      applyOffset(scroller.dataset.offset||scrollbar.scrollLeft||maxOffset);
    }
    if(!scrollbar.dataset.scrollReady){
      scrollbar.dataset.scrollReady='1';
      scrollbar.addEventListener('scroll',()=>applyOffset(scrollbar.scrollLeft),{passive:true});
      shell.querySelectorAll('.trade-chart-shift').forEach(btn=>btn.addEventListener('click',()=>applyOffset((scrollbar.scrollLeft||0)+(Number(btn.dataset.shift)||1)*Math.max(260,scroller.clientWidth*.72))));
      shell.querySelectorAll('.trade-scroll-marker').forEach(btn=>btn.addEventListener('click',()=>applyOffset((Number(btn.dataset.ratio)||0)*chartWidth-scroller.clientWidth*.5)));
    }
  });
}
function renderTradeValidation(target,data){const plans=data.plans||[];currentTradeValidationPlans=plans;const preserved=new Map();target.querySelectorAll('.trade-plan-card[data-plan-key]').forEach(card=>{const key=card.dataset.planKey,detail=card.querySelector('.trade-plan-detail'),native=card.querySelector('.trade-chart-native-scroll'),chart=card.querySelector('.trade-chart-scroll');if(detail&&!detail.classList.contains('hidden'))preserved.set(key,{html:detail.innerHTML,offset:native?native.scrollLeft:Number(chart?.dataset.offset)||0})});target.dataset.loaded='1';target.innerHTML=`<div class="trade-validation-summary">${tradeValidationSummaryHtml(data.summary||{})}</div><div class="trade-plan-list">${plans.length?groupedTradePlans(plans).map(tradeSymbolGroupCard).join(''):'<p class="empty-alert">暂无趋势验证计划。</p>'}</div>`;preserved.forEach((state,key)=>{const card=target.querySelector(`[data-plan-key="${CSS.escape(key)}"]`),detail=card?.querySelector('.trade-plan-detail'),button=card?.querySelector('.trade-detail-toggle'),chart=card?.querySelector('.trade-chart-scroll');if(!detail)return;detail.innerHTML=state.html;detail.classList.remove('hidden');if(button)button.textContent='收起K线和详细数据';if(chart)chart.dataset.offset=String(state.offset)});activateTradeChartScrolls(target)}
async function loadTradeValidation(){const target=byId('tradeValidation');if(!target)return;const hasOld=target.dataset.loaded==='1';if(!hasOld)target.innerHTML='<p class="loading">正在读取趋势验证记录…</p>';try{const data=await (await fetch('/api/trade-validation')).json();renderTradeValidation(target,data)}catch(error){if(!hasOld)target.innerHTML='<p class="empty-alert">趋势验证暂时无法读取。</p>'}finally{target.classList.remove('soft-loading')}}
document.querySelectorAll('nav a[data-view="daily-thoughts"]').forEach(link=>link.addEventListener('click',()=>loadThoughtAnalysis()));
document.querySelectorAll('nav a[data-view="trade-validation"]').forEach(link=>link.addEventListener('click',()=>loadTradeValidation()));
let tradeChartDrag=null;
function tradeChartSetOffset(scroller,value){const shell=scroller.closest('.trade-chart-shell'),scrollbar=shell?.querySelector('.trade-chart-native-scroll');if(!scrollbar)return;const max=Math.max(0,scrollbar.scrollWidth-scrollbar.clientWidth),offset=Math.max(0,Math.min(max,Number(value)||0));scrollbar.scrollLeft=offset;scroller.dataset.offset=String(offset);scroller.querySelector('.trade-chart-track')?.style.setProperty('transform',`translateX(${-offset}px)`)}
function tradeChartTimes(scroller){try{return JSON.parse(decodeURIComponent(scroller.dataset.candleTimes||'%5B%5D'))}catch(error){return []}}
function tradeChartMoveCrosshair(scroller,clientX){const line=scroller.querySelector('.trade-crosshair-line'),label=scroller.querySelector('.trade-crosshair-time'),times=tradeChartTimes(scroller);if(!line||!label||!times.length)return;const rect=scroller.getBoundingClientRect(),step=Number(scroller.dataset.candleStep)||12,left=Number(scroller.dataset.candleLeft)||26,offset=Number(scroller.dataset.offset)||0,localX=clientX-rect.left,chartX=offset+localX;let idx=Math.round((chartX-left)/step);idx=Math.max(0,Math.min(times.length-1,idx));const screenX=left+idx*step-offset;if(screenX<0||screenX>rect.width){line.classList.add('hidden');label.classList.add('hidden');return}line.style.left=`${screenX}px`;label.style.left=`${Math.max(44,Math.min(rect.width-44,screenX))}px`;label.textContent=times[idx];line.classList.remove('hidden');label.classList.remove('hidden')}
function tradeChartHideCrosshair(scroller){scroller.querySelector('.trade-crosshair-line')?.classList.add('hidden');scroller.querySelector('.trade-crosshair-time')?.classList.add('hidden')}
function tradeChartDragStart(scroller,clientX){tradeChartDrag={scroller,startX:clientX,startLeft:Number(scroller.dataset.offset)||0};scroller.classList.add('dragging')}
function tradeChartDragMove(clientX){if(!tradeChartDrag)return;tradeChartSetOffset(tradeChartDrag.scroller,tradeChartDrag.startLeft-(clientX-tradeChartDrag.startX))}
function tradeChartDragEnd(){if(!tradeChartDrag)return;tradeChartDrag.scroller.classList.remove('dragging');tradeChartDrag=null}
document.addEventListener('mousedown',event=>{const scroller=event.target.closest?.('.trade-chart-scroll');if(!scroller||event.button!==0)return;event.preventDefault();tradeChartDragStart(scroller,event.clientX)});
document.addEventListener('mousemove',event=>{const scroller=event.target.closest?.('.trade-chart-scroll');if(scroller)tradeChartMoveCrosshair(scroller,event.clientX);tradeChartDragMove(event.clientX)});
document.addEventListener('mouseup',tradeChartDragEnd);
document.addEventListener('mouseleave',tradeChartDragEnd);
document.addEventListener('mouseout',event=>{const scroller=event.target.closest?.('.trade-chart-scroll');if(scroller&&!scroller.contains(event.relatedTarget))tradeChartHideCrosshair(scroller)});
document.addEventListener('touchstart',event=>{const scroller=event.target.closest?.('.trade-chart-scroll');if(!scroller||!event.touches.length)return;tradeChartDragStart(scroller,event.touches[0].clientX)},{passive:true});
document.addEventListener('touchmove',event=>{if(!tradeChartDrag||!event.touches.length)return;event.preventDefault();tradeChartDragMove(event.touches[0].clientX)},{passive:false});
document.addEventListener('touchend',tradeChartDragEnd);
document.addEventListener('wheel',event=>{const scroller=event.target.closest?.('.trade-chart-scroll');if(!scroller)return;event.preventDefault();const current=Number(scroller.dataset.offset)||0;tradeChartSetOffset(scroller,current+(Math.abs(event.deltaY)>Math.abs(event.deltaX)?event.deltaY:event.deltaX))},{passive:false});
const activeViewId=()=>document.querySelector('.view.active')?.id||'dashboard';
let configuredPageTimers=[];
async function startConfiguredPageTimers(){configuredPageTimers.forEach(clearInterval);configuredPageTimers=[];let values={spot_market_refresh:5,dual_market_refresh:5,browser_alert_refresh:5,thought_watch_scan:300};try{const data=await (await fetch('/api/runtime-rules')).json();data.items?.forEach(item=>{if(item.enabled&&Number(item.value)>0)values[item.key]=Number(item.value)})}catch(error){}const every=(seconds,callback)=>configuredPageTimers.push(setInterval(callback,Math.max(2,seconds)*1000));every(values.spot_market_refresh,()=>{if(activeViewId()==='dashboard')loadDashboard()});every(values.spot_market_refresh,()=>{if(activeViewId()==='spot-futures')loadSpotFutures()});every(values.dual_market_refresh,()=>{if(activeViewId()==='dual-futures')loadDualFutures()});every(values.browser_alert_refresh,loadAlerts);every(30,()=>{if(activeViewId()==='thinking')loadSimpleThinking()});every(60,()=>{if(activeViewId()==='funding-trend')loadFundingTrend()});every(30,()=>{if(activeViewId()==='trade-validation')loadTradeValidation()});every(values.thought_watch_scan,()=>{if(activeViewId()==='daily-thoughts')loadThoughtAnalysis()})}
loadAuthState().then(()=>loadChatUsers().then(startChatPolling).catch(()=>{}));updateSidebarSubnav(activeViewId());renderGainersShell();renderDualFuturesShell();addDualLiquidityHeader();addDualBasisSortControls();addBasisOpeningHeaders();installGroupFrameObservers();updateSoundControls();updateSortHeaders();updateDualSortHeaders();loadDashboard();loadAlerts(true);startConfiguredPageTimers();
